package com.aipvpcoach;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("aipvpcoach")
public interface AiPvPCoachConfig extends Config
{
	@ConfigSection(
		name = "Advanced",
		description = "Advanced fight data settings",
		position = 100,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	/**
	 * Base URL of the fight tracker API (production: Azure Container Apps).
	 * Not user-configurable in the RuneLite config panel — a plain hardcoded
	 * constant, not build-time-templated, since the RuneLite Plugin Hub's
	 * "standard" build mode replaces build.gradle wholesale and would silently
	 * discard any Gradle-property-driven injection.
	 *
	 * If testing against a local backend, temporarily change this to
	 * http://localhost:3000 — do not commit that change.
	 */
	String API_BASE_URL = "https://aipvp-con.bluestone-9e8d57ef.eastus.azurecontainerapps.io";

	/**
	 * Base URL of the AiPvPCoach web app (dashboard, fight history, sign in) —
	 * distinct from API_BASE_URL because the web app and API don't share an
	 * origin in production. Not user-configurable; used by the "Open your
	 * dashboard" link in the plugin's site panel (see AiPvPSitePanel).
	 *
	 * If testing against a local frontend, temporarily change this to
	 * http://localhost:5173 — do not commit that change.
	 */
	String WEB_APP_URL = "https://aipvp.app";

	/**
	 * Seconds to wait after the opponent disappears from the scene (lag, world reload,
	 * walking out of render distance) before ending the fight as an unknown outcome.
	 * Not user-configurable; change here before packaging a build.
	 */
	int OPPONENT_LEAVE_GRACE_SECONDS = 20;

	@ConfigItem(
		keyName = "email",
		name = "Email",
		description = "If you already signed up on the AiPvPCoach website, enter that email here. "
			+ "If not, just type any email/password pair below and an account will be created "
			+ "for you automatically the first time you log in — there's no separate signup step. "
			+ "This is NOT your RuneScape/Jagex account."
	)
	default String email()
	{
		return "";
	}

	@ConfigItem(
		keyName = "password",
		name = "Password",
		description = "Your AiPvPCoach account password (created automatically on first login if "
			+ "this email doesn't have an account yet). Please do NOT enter your RuneScape/Jagex "
			+ "account password here — this plugin never needs it and it is unrelated to your "
			+ "AiPvPCoach account.",
		secret = true
	)
	default String password()
	{
		return "";
	}

	@ConfigItem(
		keyName = "saveFightFilesLocally",
		name = "Save Fight Files Locally",
		description = "When enabled, a human-readable fight log is written to ~/pvp-fights/ for each completed fight.",
		section = advancedSection
	)
	default boolean saveFightFilesLocally()
	{
		return false;
	}

	@ConfigItem(
		keyName = "uploadFightsToServer",
		name = "Upload Fights to Server",
		description = "When enabled, completed fights are uploaded to the API for storage and analysis.",
		warning = "Completed fights (attack styles, gear/prayer/potion state, HP and damage numbers, "
			+ "food eaten, and both players' RuneScape names) will be sent to AiPvPCoach's own backend "
			+ "server for storage and coaching analysis. Your RuneScape/Jagex account credentials are "
			+ "never sent. See PRIVACY.md for full details. Continue?",
		section = advancedSection
	)
	default boolean uploadFightsToServer()
	{
		return true;
	}
}

package com.aipvpcoach;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import java.io.IOException;
import java.io.PrintWriter;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "AiPvPCoach"
)
public class AiPvPCoachPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private AiPvPCoachConfig config;

	@Inject
	private EventBus eventBus;

	@Inject
	private FightRecorder fightRecorder;

	@Inject
	private FightApiClient fightApiClient;

	@Inject
	private AuthClient authClient;

	@Inject
	private ClientToolbar clientToolbar;

	private boolean pendingAuth = false;

	private AiPvPSitePanel sitePanel;
	private NavigationButton siteNavButton;

	@Override
	protected void startUp() throws Exception
	{
		log.debug("AiPvPCoach started!");
		eventBus.register(fightRecorder);
		fightRecorder.setFightCompleteListener(this::onFightComplete);
		pendingAuth = client.getGameState() == GameState.LOGGED_IN;

		sitePanel = injector.getInstance(AiPvPSitePanel.class);
		sitePanel.init();

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "site_icon.png");
		siteNavButton = NavigationButton.builder()
			.tooltip("AiPvPCoach Site")
			.icon(icon)
			.panel(sitePanel)
			.build();
		clientToolbar.addNavigation(siteNavButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.debug("AiPvPCoach stopped!");
		eventBus.unregister(fightRecorder);
		pendingAuth = false;

		clientToolbar.removeNavigation(siteNavButton);
		sitePanel.deinit();
		sitePanel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			pendingAuth = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (pendingAuth && client.getLocalPlayer() != null)
		{
			pendingAuth = false;
			authClient.authenticate(client.getLocalPlayer().getName());
		}
	}

	private static final DateTimeFormatter FILE_TIMESTAMP =
		DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss").withZone(ZoneId.systemDefault());

	private void onFightComplete(FightData fight)
	{
		FightSummary summary = FightSummary.from(fight);

		if (summary.getTotalDamageDealt() == 0 && summary.getTotalDamageTaken() == 0)
		{
			log.debug("Ignoring fight with no damage dealt or taken: {} vs {}",
				fight.getLocalPlayerName(), fight.getOpponentName());
			return;
		}

		log.debug("Fight complete: {} vs {}, outcome={}, ticks={}, events={}",
			fight.getLocalPlayerName(),
			fight.getOpponentName(),
			fight.getOutcome(),
			fight.getTotalTicks(),
			fight.getEvents().size());

		log.debug("Summary: dealt={} taken={} overhead={}% ({}/{}) offPrayer={} ({}%) food={} specs={} attacks={}",
			summary.getTotalDamageDealt(),
			summary.getTotalDamageTaken(),
			summary.overheadCorrectPct(),
			summary.getOverheadCorrectHits(),
			summary.getOverheadCheckableHits(),
			summary.getAttacksOffPrayer(),
			summary.attacksOffPrayerPct(),
			summary.getFoodEaten(),
			summary.getSpecsUsed(),
			summary.getAttackStyleCounts());

		for (FightEvent event : fight.getEvents())
		{
			log.debug("  [tick {}] {}", event.getTick(), formatEvent(event, fight));
		}

		if (config.saveFightFilesLocally())
		{
			saveFightToFile(fight, summary);
		}
		if (config.uploadFightsToServer())
		{
			fightApiClient.sendFight(fight, summary);
		}
	}

	private void saveFightToFile(FightData fight, FightSummary summary)
	{
		try
		{
			Path dir = RuneLite.RUNELITE_DIR.toPath().resolve("aipvpcoach").resolve("pvp-fights");
			Files.createDirectories(dir);

			String timestamp = FILE_TIMESTAMP.format(fight.getStartTime());
			String filename = timestamp + "_" + fight.getLocalPlayerName() + "_vs_" + fight.getOpponentName() + ".txt";
			Path file = dir.resolve(filename);

			try (PrintWriter pw = new PrintWriter(Files.newBufferedWriter(file)))
			{
				pw.printf("Fight: %s vs %s%n", fight.getLocalPlayerName(), fight.getOpponentName());
				pw.printf("Outcome: %s%n", fight.getOutcome());
				pw.printf("Duration: %d ticks%n", fight.getTotalTicks());
				pw.println();
				pw.println("--- Summary ---");
				pw.printf("Damage dealt:   %d%n", summary.getTotalDamageDealt());
				pw.printf("Damage taken:   %d%n", summary.getTotalDamageTaken());
				pw.printf("Overhead correct: %d%% (%d/%d hits)%n",
					summary.overheadCorrectPct(),
					summary.getOverheadCorrectHits(),
					summary.getOverheadCheckableHits());
				pw.printf("Off prayer:     %d/%d attacks (%d%%)%n",
					summary.getAttacksOffPrayer(),
					summary.totalAttacks(),
					summary.attacksOffPrayerPct());
				pw.printf("Food eaten:     %d items%n", summary.getFoodEaten());
				pw.printf("HP wasted:      %d%n", summary.getTotalHpWasted());
				pw.printf("Food left:      %d hp%n", summary.getFoodHealingLeft());
				pw.printf("Specs used:     %d%n", summary.getSpecsUsed());
				pw.printf("Attacks:        %s%n", summary.getAttackStyleCounts());
				pw.printf("Pot status:     potted=%d unpotted=%d brewed=%d%n",
					summary.getAttacksPotted(),
					summary.getAttacksUnpotted(),
					summary.getAttacksBrewed());
				pw.printf("Start: %s%n", fight.getStartTime());
				pw.printf("End:   %s%n", fight.getEndTime());
				GearBonuses opt = fight.getOptimalBonuses();
				if (opt != null)
				{
					pw.println();
					pw.println("Optimal attack bonuses (best available at fight start):");
					pw.printf("  Attack:   stab=%+d slash=%+d crush=%+d magic=%+d ranged=%+d%n",
						opt.getAttackStab(), opt.getAttackSlash(), opt.getAttackCrush(),
						opt.getAttackMagic(), opt.getAttackRanged());
					pw.printf("  Strength: melee=%+d ranged=%+d magic=%.0f%%%n",
						opt.getStrengthMelee(), opt.getStrengthRanged(), opt.getStrengthMagic());
				}
				DefenseBonuses def = fight.getOptimalDefenseBonuses();
				if (def != null)
				{
					pw.println();
					pw.println("Optimal tank bonuses (best available at fight start, per style):");
					pw.printf("  vs melee: stab=%+d slash=%+d crush=%+d%n",
						def.getDefStab(), def.getDefSlash(), def.getDefCrush());
					pw.printf("  vs range: %+d%n", def.getDefRange());
					pw.printf("  vs magic: %+d%n", def.getDefMagic());
				}
				pw.println();
				pw.println("--- Events ---");
				for (FightEvent event : fight.getEvents())
				{
					pw.printf("[tick %3d] %s%n", event.getTick(), formatEvent(event, fight));
				}
			}

			log.debug("Fight saved to {}", file);
		}
		catch (IOException e)
		{
			log.error("Failed to save fight log", e);
		}
	}

	private String formatEvent(FightEvent event, FightData fight)
	{
		switch (event.getType())
		{
			case ATTACK_ATTEMPTED:
			{
				StringBuilder sb = new StringBuilder("ATTACK_ATTEMPTED [").append(event.getAttackStyle()).append("]");
				sb.append(" prayer=").append(event.getOffensivePrayer() != null ? event.getOffensivePrayer() : "none");
				sb.append(" off_prayer=").append(event.isAttackOffPrayer());
				if (event.getGearBonuses() != null && fight != null && fight.getOptimalBonuses() != null)
				{
					Map<String, Integer> eff = event.getGearBonuses().effectiveness(fight.getOptimalBonuses());
					sb.append(" | eff:");
					for (Map.Entry<String, Integer> e : eff.entrySet())
					{
						sb.append(" ").append(e.getKey()).append("=").append(e.getValue()).append("%");
					}
				}
				if (event.getStatBoosts() != null && fight != null && fight.getOptimalStatBoosts() != null)
				{
					Map<String, Integer> potEff = event.getStatBoosts().effectiveness(
						fight.getOptimalStatBoosts(), event.getAttackStyle());
					if (!potEff.isEmpty())
					{
						sb.append(" | pots:");
						for (Map.Entry<String, Integer> e : potEff.entrySet())
						{
							sb.append(" ").append(e.getKey()).append("=").append(e.getValue()).append("%");
						}
					}
				}
				return sb.toString();
			}
			case DAMAGE_DEALT:
				return "DAMAGE_DEALT " + event.getAmount();
			case DAMAGE_TAKEN:
			{
				StringBuilder sb = new StringBuilder("DAMAGE_TAKEN ").append(event.getAmount());
				sb.append(" (hp=").append(event.getPlayerHp()).append(")");
				if (event.isVengeanceDamage())
				{
					sb.append(" [vengeance]");
				}
				return sb.toString();
			}
			case OPPONENT_ATTACK:
			{
				StringBuilder sb = new StringBuilder("OPPONENT_ATTACK [").append(event.getOpponentAttackStyle()).append("]");
				sb.append(" overhead=").append(event.getMyOverheadPrayer() != null ? event.getMyOverheadPrayer() : "NONE");
				sb.append(" correct=").append(event.isOverheadCorrect());
				if (event.getDefBonuses() != null && fight != null && fight.getOptimalDefenseBonuses() != null)
				{
					sb.append(" | tank_eff:");
					String style = event.getOpponentAttackStyle();
					DefenseBonuses def = event.getDefBonuses();
					DefenseBonuses opt = fight.getOptimalDefenseBonuses();
					if ("ranged".equals(style))
					{
						sb.append(" dRange=").append(pct(def.getDefRange(), opt.getDefRange())).append("%");
					}
					else if ("magic".equals(style))
					{
						sb.append(" dMagic=").append(pct(def.getDefMagic(), opt.getDefMagic())).append("%");
					}
					else if ("melee".equals(style))
					{
						sb.append(" dStab=").append(pct(def.getDefStab(), opt.getDefStab())).append("%");
						sb.append(" dSlash=").append(pct(def.getDefSlash(), opt.getDefSlash())).append("%");
						sb.append(" dCrush=").append(pct(def.getDefCrush(), opt.getDefCrush())).append("%");
					}
					else
					{
						for (Map.Entry<String, Integer> e : def.effectiveness(opt).entrySet())
						{
							sb.append(" ").append(e.getKey()).append("=").append(e.getValue()).append("%");
						}
					}
				}
				return sb.toString();
			}
			case FOOD_EATEN:
			{
				java.util.List<String> items = event.getConsumedItems();
				String label;
				switch (items.size())
				{
					case 1:  label = "single ate"; break;
					case 2:  label = "double ate"; break;
					case 3:  label = "triple ate"; break;
					default: label = items.size() + "x ate"; break;
				}
				StringBuilder sb = new StringBuilder("FOOD_EATEN ")
					.append(label).append(" ").append(String.join(", ", items))
					.append(" (hp=").append(event.getPlayerHp()).append(")");
				int wasted = FoodHealAmounts.calcWasted(items, event.getHpBeforeEating(), event.getMaxHp());
				if (wasted > 0)
				{
					sb.append(" [overeat: ").append(wasted).append(" hp wasted]");
				}
				else if (wasted < 0 && event.getHpBeforeEating() >= 0)
				{
					sb.append(" [overeat: N/A - boost item]");
				}
				return sb.toString();
			}
			case SPEC_USED:
				return "SPEC_USED";
			case SPEC_ENERGY_CHANGED:
				return "SPEC_ENERGY_CHANGED energy=" + event.getSpecEnergy() + " lightBearer=" + event.isLightBearerEquipped();
			case OVERHEAD_CHANGED:
				return "OVERHEAD_CHANGED -> " + event.getOverheadPrayer();
			case HP_SNAPSHOT:
				return "HP_SNAPSHOT hp=" + event.getPlayerHp() + " prayer=" + event.getPlayerPrayer();
			case FIGHT_START:
				return "FIGHT_START";
			case FIGHT_END:
				return "FIGHT_END loser=" + event.getLoser();
			default:
				return event.getType().name();
		}
	}

	private static int pct(int current, int optimal)
	{
		if (optimal <= 0)
		{
			// Defense bonuses can be negative (e.g. mage gear has negative dRange).
			// When optimal is 0 or negative, ratio math doesn't apply â€” return 100%
			// only if current is at least as good as optimal.
			return current >= optimal ? 100 : 0;
		}
		int p = (int) Math.round(100.0 * current / optimal);
		return Math.max(0, Math.min(100, p));
	}

	@Provides
	AiPvPCoachConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AiPvPCoachConfig.class);
	}
}

package com.aipvpcoach;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * Sidebar panel giving quick access back to the AiPvPCoach web app (Feature 36).
 *
 * "Report an issue" currently points at the AiPvPMono monorepo's issues page —
 * update this once/if the plugin is split into its own standalone repo for
 * Plugin Hub submission (see HUB_SUBMISSION.md).
 */
public class AiPvPSitePanel extends PluginPanel
{
	private static final String ISSUES_URL = "https://github.com/OmgWhoTookMyName/ai-pvp-coach/issues";

	void init()
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel linksContainer = new JPanel();
		linksContainer.setLayout(new GridLayout(0, 1, 0, 10));
		linksContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		linksContainer.add(buildLinkPanel("Open your", "AiPvPCoach dashboard", AiPvPCoachConfig.WEB_APP_URL));
		linksContainer.add(buildLinkPanel("Report an issue or", "make a suggestion", ISSUES_URL));

		add(linksContainer, BorderLayout.NORTH);
	}

	void deinit()
	{
	}

	private static JPanel buildLinkPanel(String topText, String bottomText, String url)
	{
		JPanel container = new JPanel();
		container.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		container.setLayout(new GridLayout(2, 1));
		container.setBorder(new EmptyBorder(10, 10, 10, 10));

		final Color hoverColor = ColorScheme.DARKER_GRAY_HOVER_COLOR;
		final Color pressedColor = ColorScheme.DARKER_GRAY_COLOR.brighter();

		JLabel topLine = new JLabel(topText);
		topLine.setForeground(Color.WHITE);
		topLine.setFont(FontManager.getRunescapeSmallFont());

		JLabel bottomLine = new JLabel(bottomText);
		bottomLine.setForeground(Color.WHITE);
		bottomLine.setFont(FontManager.getRunescapeSmallFont());

		container.add(topLine);
		container.add(bottomLine);

		container.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				container.setBackground(pressedColor);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				LinkBrowser.browse(url);
				container.setBackground(hoverColor);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				container.setBackground(hoverColor);
				container.setCursor(new Cursor(Cursor.HAND_CURSOR));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				container.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				container.setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
			}
		});

		return container;
	}
}

