package com.aipvpcoach;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;

@Slf4j
@Singleton
public class AuthClient
{
	static final String CONFIG_GROUP = "aipvpcoach";
	static final String TOKEN_KEY = "authToken";

	private static final String REGISTER_PATH = "/auth/register";
	private static final String LOGIN_PATH = "/auth/login";
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient http;

	@Inject
	private AiPvPCoachConfig config;

	@Inject
	private ConfigManager configManager;

	/** Returns the stored JWT, or null if not yet authenticated. */
	public String getToken()
	{
		return configManager.getConfiguration(CONFIG_GROUP, TOKEN_KEY);
	}

	/**
	 * Authenticates against the API using the configured email/password and the
	 * provided RSN. No-ops if credentials are missing or a token is already stored.
	 * Tries /register first; falls back to /login on 409 (email already registered).
	 */
	public void authenticate(String rsn)
	{
		log.debug("Beginning auth process");

		String email = config.email();
		String password = config.password();
		String baseUrl = AiPvPCoachConfig.API_BASE_URL;

		if (isBlank(email) || isBlank(password) || isBlank(baseUrl))
		{
			log.debug("authenticate skipped: email={} password={} baseUrl={}",
				isBlank(email) ? "<blank>" : email,
				isBlank(password) ? "<blank>" : "<set>",
				isBlank(baseUrl) ? "<blank>" : baseUrl);
			return;
		}

		if (!isBlank(getToken()))
		{
			log.debug("Auth token already present, skipping authentication");
			return;
		}

		String json = gson.toJson(new RegisterRequest(email, password, rsn));
		Request request = new Request.Builder()
			.url(baseUrl + REGISTER_PATH)
			.post(RequestBody.create(JSON, json))
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Registration request failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (response.code() == 409)
					{
						tryLogin(email, password, baseUrl);
						return;
					}
					if (!response.isSuccessful())
					{
						log.error("Registration failed ({}): {}", response.code(),
							response.body() != null ? response.body().string() : "");
						return;
					}
					storeToken(response);
				}
			}
		});
	}

	/**
	 * Clears the stored token and re-authenticates via login.
	 * onSuccess is called after the new token is stored.
	 */
	public void refreshToken(Runnable onSuccess)
	{
		configManager.unsetConfiguration(CONFIG_GROUP, TOKEN_KEY);
		String email = config.email();
		String password = config.password();
		String baseUrl = AiPvPCoachConfig.API_BASE_URL;
		if (isBlank(email) || isBlank(password) || isBlank(baseUrl))
		{
			log.warn("Cannot refresh token: credentials not configured");
			return;
		}
		log.debug("Refreshing auth token");
		tryLogin(email, password, baseUrl, onSuccess);
	}

	private void tryLogin(String email, String password, String baseUrl)
	{
		tryLogin(email, password, baseUrl, null);
	}

	private void tryLogin(String email, String password, String baseUrl, Runnable onSuccess)
	{
		String json = gson.toJson(new LoginRequest(email, password));
		Request request = new Request.Builder()
			.url(baseUrl + LOGIN_PATH)
			.post(RequestBody.create(JSON, json))
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Login request failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (!response.isSuccessful())
					{
						log.error("Login failed ({}): {}", response.code(),
							response.body() != null ? response.body().string() : "");
						return;
					}
					storeToken(response);
					if (onSuccess != null)
					{
						onSuccess.run();
					}
				}
			}
		});
	}

	private void storeToken(Response response) throws IOException
	{
		String body = response.body() != null ? response.body().string() : null;
		if (isBlank(body))
		{
			log.error("Auth response had no body");
			return;
		}
		AuthResponse parsed = gson.fromJson(body, AuthResponse.class);
		if (parsed == null || isBlank(parsed.token))
		{
			log.error("Auth response missing token field");
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, TOKEN_KEY, parsed.token);
		log.debug("Authenticated successfully (plan={})", parsed.plan);
	}

	private static boolean isBlank(String s)
	{
		return s == null || s.trim().isEmpty();
	}

	// ---- Request / response DTOs ----

	private static class RegisterRequest
	{
		String email, password, rsn;

		RegisterRequest(String email, String password, String rsn)
		{
			this.email = email;
			this.password = password;
			this.rsn = rsn;
		}
	}

	private static class LoginRequest
	{
		String email, password;

		LoginRequest(String email, String password)
		{
			this.email = email;
			this.password = password;
		}
	}

	private static class AuthResponse
	{
		String token;
		String plan;
	}
}

package com.aipvpcoach;

import lombok.Value;
import java.util.LinkedHashMap;
import java.util.Map;

@Value
public class DefenseBonuses
{
	int defStab;
	int defSlash;
	int defCrush;
	int defRange;
	int defMagic;

	/** Best melee defense across all three melee types. */
	public int defMelee()
	{
		return Math.max(defStab, Math.max(defSlash, defCrush));
	}

	/**
	 * Computes per-style defense effectiveness as a percentage of the optimal bonuses.
	 * Returns 100% when the optimal bonus is 0 (can't do better than 0).
	 * Clamped to 0â€“100%.
	 */
	public Map<String, Integer> effectiveness(DefenseBonuses optimal)
	{
		Map<String, Integer> result = new LinkedHashMap<>();
		result.put("dStab",  pct(defStab,  optimal.defStab));
		result.put("dSlash", pct(defSlash, optimal.defSlash));
		result.put("dCrush", pct(defCrush, optimal.defCrush));
		result.put("dRange", pct(defRange, optimal.defRange));
		result.put("dMagic", pct(defMagic, optimal.defMagic));
		return result;
	}

	private static int pct(int current, int optimal)
	{
		if (optimal <= 0)
		{
			// Defense bonuses can be negative (e.g. mage gear has negative dRange).
			// When optimal is 0 or negative, ratio math doesn't apply â€” return 100%
			// only if current is at least as good as optimal.
			return current >= optimal ? 100 : 0;
		}
		int pct = (int) Math.round(100.0 * current / optimal);
		return Math.max(0, Math.min(100, pct));
	}
}

package com.aipvpcoach;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.List;
import java.util.Map;

@Slf4j
@Singleton
public class FightApiClient
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient http;

	@Inject
	private AiPvPCoachConfig config;

	@Inject
	private AuthClient authClient;

	public void sendFight(FightData fight, FightSummary summary)
	{
		sendFight(fight, summary, false);
	}

	private void sendFight(FightData fight, FightSummary summary, boolean isRetry)
	{
		log.debug("Starting to send fight data (retry={})", isRetry);
		String baseUrl = AiPvPCoachConfig.API_BASE_URL;
		if (baseUrl.isEmpty())
		{
			return;
		}

		String json = gson.toJson(buildPayload(fight, summary));
		log.debug("Sending fight payload: {} events, {} bytes", fight.getEvents().size(), json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);
		Request.Builder builder = new Request.Builder()
			.url(baseUrl + "/fights")
			.post(RequestBody.create(JSON, json));

		String token = authClient.getToken();
		if (token != null && !token.isEmpty())
		{
			builder.header("Authorization", "Bearer " + token);
		}

		Request request = builder.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Failed to send fight to API: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (response.code() == 401 && !isRetry)
					{
						log.debug("Got 401, refreshing token and retrying");
						authClient.refreshToken(() -> sendFight(fight, summary, true));
						return;
					}
					if (!response.isSuccessful())
					{
						log.error("API returned {}: {}",
							response.code(),
							response.body() != null ? response.body().string() : "(no body)");
					}
				}
			}
		});
	}

	// -------------------------------------------------------------------------
	// Payload assembly
	// -------------------------------------------------------------------------

	private Payload buildPayload(FightData fight, FightSummary summary)
	{
		Payload p = new Payload();
		p.playerName = fight.getLocalPlayerName();
		p.opponentName = fight.getOpponentName();
		p.outcome = fight.getOutcome() != null ? fight.getOutcome().toUpperCase() : "UNKNOWN";
		p.startTime = fight.getStartTime().toString();
		p.endTime = fight.getEndTime().toString();
		p.durationTicks = fight.getTotalTicks();
		p.summary = buildSummary(summary);
		p.optimalGear = buildGear(fight.getOptimalBonuses());
		p.optimalDefense = buildDefense(fight.getOptimalDefenseBonuses());
		p.optimalStats = buildStats(fight.getOptimalStatBoosts());
		p.baseStats = buildStats(fight.getBaseStatBoosts());
		GearBonuses optimalGear = fight.getOptimalBonuses();
		DefenseBonuses optimalDef = fight.getOptimalDefenseBonuses();
		StatBoosts optimalStat = fight.getOptimalStatBoosts();
		p.events = fight.getEvents().stream()
			.map(e -> buildEvent(e, optimalGear, optimalDef, optimalStat))
			.collect(java.util.stream.Collectors.toList());
		return p;
	}

	private SummaryPayload buildSummary(FightSummary s)
	{
		SummaryPayload sp = new SummaryPayload();
		sp.totalDamageDealt = s.getTotalDamageDealt();
		sp.totalDamageTaken = s.getTotalDamageTaken();
		sp.overheadCheckableHits = s.getOverheadCheckableHits();
		sp.overheadCorrectHits = s.getOverheadCorrectHits();
		sp.attacksOffPrayer = s.getAttacksOffPrayer();
		sp.totalAttacks = s.totalAttacks();
		sp.attackStyleCounts = s.getAttackStyleCounts();
		sp.foodEaten = s.getFoodEaten();
		sp.foodHealingLeft = s.getFoodHealingLeft();
		sp.totalHpWasted = s.getTotalHpWasted();
		sp.specsUsed = s.getSpecsUsed();
		sp.attacksPotted = s.getAttacksPotted();
		sp.attacksUnpotted = s.getAttacksUnpotted();
		sp.attacksBrewed = s.getAttacksBrewed();
		sp.avgOffensiveGearEff = s.getAvgOffensiveGearEff();
		sp.avgOffensiveStatEff = s.getAvgOffensiveStatEff();
		sp.avgDefensiveTankEff = s.getAvgDefensiveTankEff();
		return sp;
	}

	private GearPayload buildGear(GearBonuses g)
	{
		if (g == null)
		{
			return null;
		}
		GearPayload gp = new GearPayload();
		gp.attackStab = g.getAttackStab();
		gp.attackSlash = g.getAttackSlash();
		gp.attackCrush = g.getAttackCrush();
		gp.attackMagic = g.getAttackMagic();
		gp.attackRanged = g.getAttackRanged();
		gp.strengthMelee = g.getStrengthMelee();
		gp.strengthRanged = g.getStrengthRanged();
		gp.strengthMagic = g.getStrengthMagic();
		return gp;
	}

	private DefensePayload buildDefense(DefenseBonuses d)
	{
		if (d == null)
		{
			return null;
		}
		DefensePayload dp = new DefensePayload();
		dp.defStab = d.getDefStab();
		dp.defSlash = d.getDefSlash();
		dp.defCrush = d.getDefCrush();
		dp.defRange = d.getDefRange();
		dp.defMagic = d.getDefMagic();
		return dp;
	}

	private StatsPayload buildStats(StatBoosts s)
	{
		if (s == null)
		{
			return null;
		}
		StatsPayload sp = new StatsPayload();
		sp.attack = s.getAttack();
		sp.strength = s.getStrength();
		sp.ranged = s.getRanged();
		sp.magic = s.getMagic();
		return sp;
	}

	private EventPayload buildEvent(FightEvent e, GearBonuses optimalGear, DefenseBonuses optimalDef, StatBoosts optimalStat)
	{
		EventPayload ep = new EventPayload();
		ep.tick = e.getTick();
		ep.type = e.getType().name();
		ep.playerHp = e.getPlayerHp();
		ep.playerPrayer = e.getPlayerPrayer();

		switch (e.getType())
		{
			case FIGHT_START:
				ep.specEnergy = e.getSpecEnergy() >= 0 ? e.getSpecEnergy() : null;
				ep.lightBearerEquipped = e.isLightBearerEquipped();
				ep.maxHp = e.getMaxHp() > 0 ? e.getMaxHp() : null;
				break;

			case ATTACK_ATTEMPTED:
				ep.attackStyle = e.getAttackStyle();
				ep.offensivePrayer = e.getOffensivePrayer();
				ep.attackOffPrayer = e.isAttackOffPrayer();
				if (e.isSpecialAttack()) ep.specialAttack = true;
				ep.gearBonuses = buildGear(e.getGearBonuses());
				ep.statBoosts = buildStats(e.getStatBoosts());
				ep.playerWeaponId = e.getPlayerWeaponId() != -1 ? e.getPlayerWeaponId() : null;
				ep.attackAnimId = e.getAttackAnimId() >= 0 ? e.getAttackAnimId() : null;
				ep.opponentHp = e.getOpponentHp() >= 0 ? e.getOpponentHp() : null;
				if (optimalGear != null && e.getGearBonuses() != null)
				{
					ep.gearEffectiveness = e.getGearBonuses().effectiveness(optimalGear);
				}
				if (optimalStat != null && e.getStatBoosts() != null && e.getAttackStyle() != null)
				{
					ep.statEffectiveness = e.getStatBoosts().effectiveness(optimalStat, e.getAttackStyle());
				}
				if ("melee".equals(e.getAttackStyle()))
				{
					ep.meleeSubStyle = MeleeWeaponStyle.resolve(e.getPlayerWeaponId(), e.getGearBonuses());
				}
				break;

			case DAMAGE_DEALT:
				ep.amount = e.getAmount();
				break;

			case DAMAGE_TAKEN:
				ep.amount = e.getAmount();
				if (e.isVengeanceDamage()) ep.vengeanceDamage = true;
				if (e.isOpponentOnSmite()) ep.opponentOnSmite = true;
				break;

			case OPPONENT_ATTACK:
				ep.opponentAttackStyle = e.getOpponentAttackStyle();
				ep.myOverheadPrayer = e.getMyOverheadPrayer();
				ep.overheadCorrect = e.isOverheadCorrect();
				if (e.isSpecialAttack()) ep.specialAttack = true;
				ep.defBonuses = buildDefense(e.getDefBonuses());
				ep.opponentWeaponId = e.getOpponentWeaponId() != -1 ? e.getOpponentWeaponId() : null;
				ep.opponentAnimId = e.getOpponentAnimId() >= 0 ? e.getOpponentAnimId() : null;
				if (optimalDef != null && e.getDefBonuses() != null)
				{
					ep.defEffectiveness = e.getDefBonuses().effectiveness(optimalDef);
				}
				ep.opponentMeleeSubStyle = e.getOpponentMeleeSubStyle();
				ep.opponentGearBonuses = buildGear(e.getOpponentGearBonuses());
				break;

			case FOOD_EATEN:
				ep.consumedItems = e.getConsumedItems();
				ep.amount = e.getAmount();
				ep.hpBeforeEating = e.getHpBeforeEating() >= 0 ? e.getHpBeforeEating() : null;
				ep.maxHp = e.getMaxHp() > 0 ? e.getMaxHp() : null;
				break;

			case SPEC_USED:
				break;

			case SPEC_ENERGY_CHANGED:
				ep.specEnergy = e.getSpecEnergy() >= 0 ? e.getSpecEnergy() : null;
				ep.lightBearerEquipped = e.isLightBearerEquipped();
				break;

			case OVERHEAD_CHANGED:
				ep.overheadPrayer = e.getOverheadPrayer();
				break;

			case PLAYER_OVERHEAD_CHANGED:
				ep.myOverheadPrayer = e.getMyOverheadPrayer();
				break;

			case GEAR_CHANGED:
				ep.slotsChanged = e.getSlotsChanged();
				ep.gearBonuses = buildGear(e.getGearBonuses());
				ep.defBonuses = buildDefense(e.getDefBonuses());
				ep.playerWeaponId = e.getPlayerWeaponId() != -1 ? e.getPlayerWeaponId() : null;
				if (optimalGear != null && e.getGearBonuses() != null)
				{
					ep.gearEffectiveness = e.getGearBonuses().effectiveness(optimalGear);
				}
				if (optimalDef != null && e.getDefBonuses() != null)
				{
					ep.defEffectiveness = e.getDefBonuses().effectiveness(optimalDef);
				}
				break;

			case HP_SNAPSHOT:
				break;

			case FIGHT_END:
				ep.loser = e.getLoser();
				break;
		}

		return ep;
	}

	// -------------------------------------------------------------------------
	// JSON DTOs
	// -------------------------------------------------------------------------

	private static class Payload
	{
		String playerName, opponentName, outcome, startTime, endTime;
		int durationTicks;
		SummaryPayload summary;
		GearPayload optimalGear;
		DefensePayload optimalDefense;
		StatsPayload optimalStats, baseStats;
		List<EventPayload> events;
	}

	private static class SummaryPayload
	{
		int totalDamageDealt, totalDamageTaken;
		int overheadCheckableHits, overheadCorrectHits;
		int attacksOffPrayer, totalAttacks;
		Map<String, Integer> attackStyleCounts;
		int foodEaten, foodHealingLeft, totalHpWasted;
		int specsUsed;
		int attacksPotted, attacksUnpotted, attacksBrewed;
		Map<String, Integer> avgOffensiveGearEff, avgOffensiveStatEff, avgDefensiveTankEff;
	}

	private static class GearPayload
	{
		int attackStab, attackSlash, attackCrush, attackMagic, attackRanged;
		int strengthMelee, strengthRanged;
		float strengthMagic;
	}

	private static class DefensePayload
	{
		int defStab, defSlash, defCrush, defRange, defMagic;
	}

	private static class StatsPayload
	{
		int attack, strength, ranged, magic;
	}

	private static class EventPayload
	{
		int tick, playerHp, playerPrayer;
		String type;
		Integer amount, hpBeforeEating, maxHp;
		String attackStyle, offensivePrayer, opponentAttackStyle, myOverheadPrayer, overheadPrayer, loser;
		Boolean attackOffPrayer, vengeanceDamage, overheadCorrect, specialAttack, opponentOnSmite;
		Integer slotsChanged;
		GearPayload gearBonuses;
		DefensePayload defBonuses;
		StatsPayload statBoosts;
		Integer playerWeaponId, opponentWeaponId;
		Integer attackAnimId, opponentAnimId;
		Integer opponentHp;
		String meleeSubStyle, opponentMeleeSubStyle;
		GearPayload opponentGearBonuses;
		Map<String, Integer> gearEffectiveness, statEffectiveness, defEffectiveness;
		List<String> consumedItems;
		Integer specEnergy;
		Boolean lightBearerEquipped;
	}
}

