	/** Item ID of the opponent's equipped weapon at the time of an OPPONENT_ATTACK event. -1 if none. */
	int opponentWeaponId;
	/** Approximate opponent HP at the time of an ATTACK_ATTEMPTED event, derived from health ratio. -1 if not yet visible. */
	@Builder.Default int opponentHp = -1;
	/** Raw animation ID that triggered an ATTACK_ATTEMPTED event. Used to identify magic spell type. -1 if not set. */
	@Builder.Default int attackAnimId = -1;
	/** Raw animation ID of the opponent's attack that triggered an OPPONENT_ATTACK event. -1 if not set. */
	@Builder.Default int opponentAnimId = -1;
	/** Resolved melee sub-style ("stab"/"slash"/"crush") for the opponent's weapon. Null for non-melee or unresolvable. */
	String opponentMeleeSubStyle;
	/** Full gear str bonuses for the opponent, read from PlayerComposition at animation time. Null if not captured. */
	GearBonuses opponentGearBonuses;
	boolean overheadCorrect;
	boolean vengeanceDamage;
	boolean attackOffPrayer;
	boolean specialAttack;
	/** True if the opponent had Smite active when this DAMAGE_TAKEN hitsplat landed. */
	boolean opponentOnSmite;
	/** Number of equipment slots that changed this tick. Set on GEAR_CHANGED events. */
	int slotsChanged;
	@Singular("consumedItem") List<String> consumedItems;
	/** HP before any item was consumed this tick. -1 if not captured. */
	int hpBeforeEating;
	/** Base (unbooosted) max HP at the time of eating. Used for overeat calculation. */
	int maxHp;
	/** Special attack energy percent (0-100) at a FIGHT_START or SPEC_ENERGY_CHANGED event. -1 if not set. */
	@Builder.Default int specEnergy = -1;
	/** True if a Lightbearer ring was equipped at a FIGHT_START or SPEC_ENERGY_CHANGED event. */
	boolean lightBearerEquipped;
}

