@Slf4j
public class FightRecorder
{
	private static final int HP_SNAPSHOT_INTERVAL = 5;
	private static final int FIGHT_COOLDOWN_TICKS = 10;
	// Minimum ticks between recorded attack attempts. Filters duplicate AnimationChanged
	// events caused by fizzled spells (e.g. death-dot stepping under), where the game
	// resets the attack cycle and re-fires the animation 1 tick later.
	// Safe floor: shortest real PvP attack cycle is 4 ticks (standard auto-cast).
	private static final int MIN_ATTACK_COOLDOWN_TICKS = 3;
	// Ring equipment slot index in ItemContainer(EQUIPMENT).getItems() (same array as lastEquipmentItems).
	private static final int SLOT_RING = 12;
	// Lightbearer ring item ID (OSRS wiki #25975). Doubles special attack energy regen rate.
	private static final int LIGHTBEARER_ITEM_ID = 25975;

	public interface FightCompleteListener
	{
		void onFightComplete(FightData fight);
	}

	@Inject
	private Client client;

	@Inject
	private GearAnalyzer gearAnalyzer;

	@Inject
	private ItemManager itemManager;

	@Setter
	private FightCompleteListener fightCompleteListener;

	private boolean inFight = false;
	private Player opponent = null;
	private String opponentName = null;
	private int fightStartTick = 0;
	private int currentTick = 0;
	private Instant fightStartTime = null;
	private final List<FightEvent> events = new ArrayList<>();
	private GearBonuses optimalBonuses = null;
	private DefenseBonuses optimalDefenseBonuses = null;
	private StatBoosts optimalStatBoosts = null;
	private StatBoosts baseStatBoosts = null;
	private int cooldownUntilTick = 0;

	// Pending fight state: click-to-attack doesn't start a fight until either
	// the player's attack animation fires or the player takes damage.
	private boolean pendingFightInteraction = false;
	private Player pendingOpponent = null;
	private String pendingOpponentName = null;
	private int pendingFightStartTick = 0;
	private Instant pendingFightStartTime = null;
	// Snapshotted at click-to-attack time (tryStartFight), not at confirmation time. If the
	// confirming attack animation is itself a special attack, the SPECIAL_ATTACK_PERCENT varp
	// has already been decremented by the time confirmPendingFight() runs in that same
	// onAnimationChanged callback, so a live re-read there would record post-spec energy (often
	// 0) as the fight's "starting" energy.
	private int pendingSpecEnergy = 0;
	private boolean pendingLightBearerEquipped = false;
	private static final int PENDING_FIGHT_TIMEOUT_TICKS = 20;

	private String lastOverheadPrayer;
	private String lastMyOverheadPrayer;
	private int foodHealingLeft = -1;

	// Eat/drink clicks buffered from MenuOptionClicked; flushed each GameTick.
	private final List<String> pendingConsumables = new ArrayList<>();
	private final List<Integer> pendingConsumableSlots = new ArrayList<>();
	private Item[] inventorySnapshot = null;
	private int hpBeforeEating = -1;
	private boolean inventoryChangedThisTick = false;
	private int pendingConsumablesAge = 0;

	private String opponentLastAttackStyle;
	private boolean opponentVengeancePending = false;
	private boolean equipmentChangedThisTick = false;
	private Item[] lastEquipmentItems = null;
	// When ActorDeath fires, we defer ending the fight to the next GameTick so that
	// any pending events on the same tick are flushed first.
	private boolean pendingFightEnd = false;
	private String pendingFightOutcome = null;
	private String pendingFightLoser = null;
	private int lastPlayerAttackTick = -MIN_ATTACK_COOLDOWN_TICKS;
	// Tick the opponent was first observed missing from the scene, or -1 if not currently missing.
	private int opponentMissingSinceTick = -1;

	/**
	 * A pending OPPONENT_ATTACK event waiting for defBonuses to be resolved in onGameTick.
	 *
	 * All opponent attacks are deferred to onGameTick so that any same-tick gear swap
	 * is reflected in the equipment before the defense snapshot is taken. Overhead is
	 * captured at animation time (correct, since the server calculates the defense roll
	 * when the attack fires, not when the hitsplat lands).
	 *
	 * For animations whose style cannot be determined from the animation ID alone,
	 * styleDeferred=true causes onGameTick to re-read the opponent's equipment one
	 * tick later, by which point any same-tick gear swap is visible in PlayerComposition.
	 */
	private static class PendingOpponentAttack
	{
		int tick;
		String attackStyle;
		boolean styleDeferred;
		String myOverhead;
		int playerHp;
		int playerPrayer;
		int weaponId = -1;
		boolean specialAttack;
		int animId = -1;
		GearBonuses opponentGearBonuses;
	}

	private final List<PendingOpponentAttack> pendingOpponentAttacks = new ArrayList<>();

	/**
	 * A pending ATTACK_ATTEMPTED event waiting for prayer state to be resolved in onGameTick.
	 *
	 * OSRS processes prayer switches before combat calculations, so a same-tick prayer switch
	 * always counts as on-prayer. Deferring to onGameTick ensures onVarbitChanged has already
	 * updated lastOverheadPrayer before attackOffPrayer is evaluated.
	 */
	private static class PendingPlayerAttack
	{
		int tick;
		String attackStyle;
		String offensivePrayer;
		GearBonuses gearBonuses;
		int playerWeaponId;
		int playerHp;
		int playerPrayer;
		StatBoosts statBoosts;
		boolean specialAttack;
		int animId = -1;
		int opponentHp = -1;
	}

	private final List<PendingPlayerAttack> pendingPlayerAttacks = new ArrayList<>();


	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (inFight)
		{
			return;
		}

		Actor source = event.getSource();
		Actor target = event.getTarget();

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		if (source == localPlayer && target instanceof Player)
		{
			tryStartFight((Player) target);
		}
		else if (target == localPlayer && source instanceof Player)
		{
			tryStartFight((Player) source);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		currentTick++;

		// Discard pending fight if no confirmation within timeout
		if (pendingFightInteraction && currentTick - pendingFightStartTick >= PENDING_FIGHT_TIMEOUT_TICKS)
		{
			log.debug("Pending fight timeout: {} (no attack or damage within {} ticks)",
				pendingOpponentName, PENDING_FIGHT_TIMEOUT_TICKS);
			pendingFightInteraction = false;
			pendingOpponent = null;
			pendingOpponentName = null;
		}

		if (!inFight)
		{
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer == null)
			{
				return;
			}
			Actor target = localPlayer.getInteracting();
			if (target instanceof Player)
			{
				tryStartFight((Player) target);
			}
			return;
		}

		// Settle the player's own overhead prayer once per tick, after this tick's
		// varbit updates have all landed. A direct switch between two protect prayers
		// fires two separate toggles (old off, new on) within the same tick — reading
		// only here, at the end, means we record the tick's real final state instead of
		// the transient "NONE" between those two toggles. See onVarbitChanged for why
		// PLAYER_OVERHEAD_CHANGED isn't emitted from there.
		String myOverheadNow = localOverheadPrayer();
		if (!myOverheadNow.equals(lastMyOverheadPrayer))
		{
			events.add(FightEvent.builder()
				.tick(currentTick - fightStartTick)
				.type(FightEventType.PLAYER_OVERHEAD_CHANGED)
				.myOverheadPrayer(myOverheadNow)
				.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
				.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
				.build());
			lastMyOverheadPrayer = myOverheadNow;
		}

		// Correct any deferred styles: opponent may have gear-swapped in the same tick
		// as the animation, so PlayerComposition now reflects the correct weapon.
		for (PendingOpponentAttack pa : pendingOpponentAttacks)
		{
			if (pa.styleDeferred && opponent != null)
			{
				pa.attackStyle = gearAnalyzer.getAttackStyleForPlayer(opponent);
				opponentLastAttackStyle = pa.attackStyle;
				pa.styleDeferred = false;
				log.debug("Opponent style corrected (deferred): {}", pa.attackStyle);
			}
		}

		// Resolve attackOffPrayer and fire all pending ATTACK_ATTEMPTED events.
		// Read opponent.getOverheadIcon() here rather than lastOverheadPrayer: PlayerComposition
		// is updated from the server packet before onGameTick fires, so this is always current.
		// lastOverheadPrayer can be stale if onVarbitChanged never fired this tick (no local
		// varbit changed), which would cause a false off-prayer result for same-tick switches.
		if (!pendingPlayerAttacks.isEmpty())
		{
			String overheadNow = (opponent != null) ? headIconName(opponent.getOverheadIcon()) : lastOverheadPrayer;
			for (PendingPlayerAttack ppa : pendingPlayerAttacks)
			{
				events.add(FightEvent.builder()
					.tick(ppa.tick)
					.type(FightEventType.ATTACK_ATTEMPTED)
					.attackStyle(ppa.attackStyle)
					.offensivePrayer(ppa.offensivePrayer)
					.gearBonuses(ppa.gearBonuses)
					.playerWeaponId(ppa.playerWeaponId)
					.playerHp(ppa.playerHp)
					.playerPrayer(ppa.playerPrayer)
					.attackOffPrayer(isAttackOffPrayer(ppa.attackStyle, overheadNow))
					.statBoosts(ppa.statBoosts)
					.specialAttack(ppa.specialAttack)
					.attackAnimId(ppa.animId)
					.opponentHp(ppa.opponentHp)
					.build());
			}
			pendingPlayerAttacks.clear();
		}

		// Resolve defBonuses and fire all pending OPPONENT_ATTACK events.
		// Snapshot is taken here so any same-tick ItemContainerChanged has already fired.
		if (!pendingOpponentAttacks.isEmpty())
		{
			DefenseBonuses snapshot = gearAnalyzer.getCurrentDefenseBonuses();
			for (PendingOpponentAttack pa : pendingOpponentAttacks)
			{
				events.add(FightEvent.builder()
					.tick(pa.tick)
					.type(FightEventType.OPPONENT_ATTACK)
					.opponentAttackStyle(pa.attackStyle)
					.opponentWeaponId(pa.weaponId)
					.opponentMeleeSubStyle("melee".equals(pa.attackStyle) ? gearAnalyzer.getMeleeSubStyle(pa.weaponId) : null)
					.myOverheadPrayer(pa.myOverhead)
					.overheadCorrect(overheadCorrect(pa.myOverhead, pa.attackStyle))
					.defBonuses(snapshot)
					.playerHp(pa.playerHp)
					.playerPrayer(pa.playerPrayer)
					.specialAttack(pa.specialAttack)
					.opponentAnimId(pa.animId)
					.opponentGearBonuses(pa.opponentGearBonuses)
					.build());
			}
			pendingOpponentAttacks.clear();
		}

		// If ActorDeath fired last tick, all pending events are now flushed and we
		// can safely end the fight.
		if (pendingFightEnd)
		{
			int t = currentTick - fightStartTick;
			events.add(FightEvent.builder()
				.tick(t)
				.type(FightEventType.FIGHT_END)
				.loser(pendingFightLoser)
				.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
				.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
				.build());
			pendingFightEnd = false;
			String outcome = pendingFightOutcome;
			pendingFightOutcome = null;
			pendingFightLoser = null;
			endFight(outcome);
			return;
		}

		int ticksIntoCombat = currentTick - fightStartTick;

		if (!client.getPlayers().contains(opponent))
		{
			// Opponent may have briefly left render distance, lagged out, or been reissued
			// a new Player object (e.g. after a world reload) — try to reacquire by name
			// before giving up on the fight.
			Player reacquired = findPlayerByName(opponentName);
			if (reacquired != null)
			{
				log.debug("Opponent reacquired: {}", opponentName);
				opponent = reacquired;
				opponentMissingSinceTick = -1;
			}
			else
			{
				if (opponentMissingSinceTick == -1)
				{
					opponentMissingSinceTick = currentTick;
					log.debug("Opponent left the scene, waiting up to {}s for them to return",
						AiPvPCoachConfig.OPPONENT_LEAVE_GRACE_SECONDS);
				}

				int graceTicks = (int) Math.round(AiPvPCoachConfig.OPPONENT_LEAVE_GRACE_SECONDS / 0.6);
				if (currentTick - opponentMissingSinceTick < graceTicks)
				{
					return;
				}

				log.debug("Opponent did not return within grace period, ending fight as unknown");
				events.add(FightEvent.builder()
					.tick(ticksIntoCombat)
					.type(FightEventType.FIGHT_END)
					.loser("unknown")
					.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
					.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
					.build());
				endFight("unknown");
				return;
			}
		}
		else
		{
			opponentMissingSinceTick = -1;
		}

		if (lastEquipmentItems == null)
		{
			ItemContainer eqInit = client.getItemContainer(InventoryID.EQUIPMENT);
			if (eqInit != null)
			{
				lastEquipmentItems = eqInit.getItems().clone();
			}
		}

		if (equipmentChangedThisTick)
		{
			GearBonuses newGear = gearAnalyzer.getCurrentBonuses();
			DefenseBonuses newDef = gearAnalyzer.getCurrentDefenseBonuses();

			int changed = 0;
			if (lastEquipmentItems != null)
			{
				ItemContainer eq = client.getItemContainer(InventoryID.EQUIPMENT);
				if (eq != null)
				{
					Item[] newItems = eq.getItems();
					for (int i = 0; i < Math.min(lastEquipmentItems.length, newItems.length); i++)
					{
						if (lastEquipmentItems[i].getId() != newItems[i].getId())
						{
							changed++;
						}
					}
				}
			}

			if (changed > 0)
			{
				events.add(FightEvent.builder()
					.tick(ticksIntoCombat)
					.type(FightEventType.GEAR_CHANGED)
					.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
					.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
					.gearBonuses(newGear)
					.defBonuses(newDef)
					.slotsChanged(changed)
					.playerWeaponId(gearAnalyzer.getPlayerWeaponId())
					.build());

				log.debug("GEAR_CHANGED at tick {}: {} slot(s) changed", ticksIntoCombat, changed);
			}
			equipmentChangedThisTick = false;
		}

		if (ticksIntoCombat > 0 && ticksIntoCombat % HP_SNAPSHOT_INTERVAL == 0)
		{
			events.add(FightEvent.builder()
				.tick(ticksIntoCombat)
				.type(FightEventType.HP_SNAPSHOT)
				.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
				.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
				.build());
		}

		// Flush eat/drink buffer. Confirmed by the inventory changing this tick â€”
		// if the server rejected the action (pot-blocked, etc.) no inventory update
		// arrives and the buffer is discarded.
		// We wait up to 2 ticks for confirmation: a click made just before GameTick
		// fires will have its inventory confirmation arrive on the following tick.
		if (!pendingConsumables.isEmpty())
		{
			if (inventoryChangedThisTick)
			{
				FightEvent.FightEventBuilder builder = FightEvent.builder()
					.tick(ticksIntoCombat)
					.type(FightEventType.FOOD_EATEN)
					.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
					.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
					.hpBeforeEating(hpBeforeEating)
					.maxHp(client.getRealSkillLevel(Skill.HITPOINTS));
				for (String item : pendingConsumables)
				{
					builder.consumedItem(item);
				}
				events.add(builder.build());
				log.debug("Consumed {} item(s): {}", pendingConsumables.size(), pendingConsumables);
				pendingConsumables.clear();
				pendingConsumableSlots.clear();
				inventorySnapshot = null;
				hpBeforeEating = -1;
				pendingConsumablesAge = 0;
			}
			else
			{
				pendingConsumablesAge++;
				if (pendingConsumablesAge >= 2)
				{
					log.debug("Discarding {} unconfirmed eat/drink click(s) (no inventory change after 2 ticks): {}",
						pendingConsumables.size(), pendingConsumables);
					pendingConsumables.clear();
					pendingConsumableSlots.clear();
					inventorySnapshot = null;
					hpBeforeEating = -1;
					pendingConsumablesAge = 0;
				}
			}
		}
		inventoryChangedThisTick = false;

		ItemContainer equipmentNow = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipmentNow != null)
		{
			lastEquipmentItems = equipmentNow.getItems().clone();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor target = event.getActor();
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		// Confirm pending fight if the local player takes damage
		if (pendingFightInteraction && target == localPlayer)
		{
			confirmPendingFight();
		}

		if (!inFight)
		{
			return;
		}

		int damage = event.getHitsplat().getAmount();
		int ticksIntoCombat = currentTick - fightStartTick;

		if (target == localPlayer)
		{
			boolean isVengeance = opponentVengeancePending;
			opponentVengeancePending = false;

			int hp = client.getBoostedSkillLevel(Skill.HITPOINTS);
			int prayer = client.getBoostedSkillLevel(Skill.PRAYER);

			boolean smite = opponent != null && opponent.getOverheadIcon() == HeadIcon.SMITE;

			if (isVengeance)
			{
				events.add(FightEvent.builder()
					.tick(ticksIntoCombat)
					.type(FightEventType.DAMAGE_TAKEN)
					.amount(damage)
					.playerHp(hp)
					.playerPrayer(prayer)
					.vengeanceDamage(true)
					.opponentOnSmite(smite)
					.build());
				return;
			}

			events.add(FightEvent.builder()
				.tick(ticksIntoCombat)
				.type(FightEventType.DAMAGE_TAKEN)
				.amount(damage)
				.playerHp(hp)
				.playerPrayer(prayer)
				.opponentOnSmite(smite)
				.build());
		}
		else if (target == opponent)
		{
			events.add(FightEvent.builder()
				.tick(ticksIntoCombat)
				.type(FightEventType.DAMAGE_DEALT)
				.amount(damage)
				.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
				.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
				.build());
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Actor actor = event.getActor();
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		// Confirm pending fight if the local player plays an attack animation
		if (pendingFightInteraction && actor == localPlayer)
		{
			int anim = actor.getAnimation();
			if (anim != -1 && !AnimationIDs.NON_ATTACK_ANIMATIONS.contains(anim))
			{
				confirmPendingFight();
			}
		}

		if (!inFight)
		{
			return;
		}

		int anim = actor.getAnimation();
		int ticksIntoCombat = currentTick - fightStartTick;

		if (actor == localPlayer)
		{
			log.debug("Local anim {} at tick {}", anim, ticksIntoCombat);
			if (anim != -1 && !AnimationIDs.NON_ATTACK_ANIMATIONS.contains(anim))
			{
				if (ticksIntoCombat - lastPlayerAttackTick >= MIN_ATTACK_COOLDOWN_TICKS)
				{
					String style;
					if (AnimationIDs.MELEE_ATTACK_ANIMATIONS.contains(anim))
					{
						style = "melee";
					}
					else if (AnimationIDs.RANGED_ATTACK_ANIMATIONS.contains(anim))
					{
						style = "ranged";
					}
					else if (AnimationIDs.MAGIC_ATTACK_ANIMATIONS.contains(anim))
					{
						style = "magic";
					}
					else
					{
						style = gearAnalyzer.getAttackStyle();
					}
					PendingPlayerAttack ppa = new PendingPlayerAttack();
					ppa.tick = ticksIntoCombat;
					ppa.attackStyle = style;
					ppa.offensivePrayer = activeOffensivePrayer(style);
					ppa.gearBonuses = gearAnalyzer.getCurrentBonuses();
					ppa.playerWeaponId = gearAnalyzer.getPlayerWeaponId();
					ppa.playerHp = client.getBoostedSkillLevel(Skill.HITPOINTS);
					ppa.playerPrayer = client.getBoostedSkillLevel(Skill.PRAYER);
					ppa.statBoosts = currentStatBoosts();
					ppa.specialAttack = AnimationIDs.SPECIAL_ATTACK_ANIMATIONS.contains(anim);
					ppa.animId = anim;
					if (opponent != null)
					{
						int ratio = opponent.getHealthRatio();
						int scale = opponent.getHealthScale();
						ppa.opponentHp = (ratio >= 0 && scale > 0)
							? (int) Math.round((double) ratio / scale * 99)
							: -1;
					}
					pendingPlayerAttacks.add(ppa);
					lastPlayerAttackTick = ticksIntoCombat;
					if (ppa.specialAttack)
					{
						events.add(FightEvent.builder()
							.tick(ticksIntoCombat)
							.type(FightEventType.SPEC_USED)
							.playerHp(ppa.playerHp)
							.playerPrayer(ppa.playerPrayer)
							.build());
					}
				}
			}
		}
		else if (actor == opponent && anim != -1 && !AnimationIDs.NON_ATTACK_ANIMATIONS.contains(anim))
		{
			PendingOpponentAttack pa = new PendingOpponentAttack();
			pa.tick = ticksIntoCombat;
			pa.myOverhead = localOverheadPrayer();
			pa.playerHp = client.getBoostedSkillLevel(Skill.HITPOINTS);
			pa.playerPrayer = client.getBoostedSkillLevel(Skill.PRAYER);
			pa.weaponId = (opponent.getPlayerComposition() != null)
				? opponent.getPlayerComposition().getEquipmentId(KitType.WEAPON)
				: -1;
			pa.specialAttack = AnimationIDs.SPECIAL_ATTACK_ANIMATIONS.contains(anim);
			pa.animId = anim;
			pa.opponentGearBonuses = gearAnalyzer.getBonusesForPlayer(opponent);

			if (AnimationIDs.MELEE_ATTACK_ANIMATIONS.contains(anim))
			{
				// Animation ID is authoritative for melee. Do NOT read from
				// PlayerComposition â€” opponent may have already swapped back to
				// ranged/magic in the same tick.
				pa.attackStyle = "melee";
				pa.styleDeferred = false;
				opponentLastAttackStyle = "melee";
			}
			else if (AnimationIDs.RANGED_ATTACK_ANIMATIONS.contains(anim))
			{
				pa.attackStyle = "ranged";
				pa.styleDeferred = false;
				opponentLastAttackStyle = "ranged";
				log.debug("Opponent style forced to ranged by animation {}", anim);
			}
			else if (AnimationIDs.MAGIC_ATTACK_ANIMATIONS.contains(anim))
			{
				pa.attackStyle = "magic";
				pa.styleDeferred = false;
				opponentLastAttackStyle = "magic";
				log.debug("Opponent style forced to magic by animation {}", anim);
			}
			else
			{
				// Unknown animation â€” infer from equipment and defer one tick so any
				// same-tick gear swap is reflected in PlayerComposition first.
				pa.attackStyle = gearAnalyzer.getAttackStyleForPlayer(opponent);
				pa.styleDeferred = true;
				opponentLastAttackStyle = pa.attackStyle;
				log.debug("Opponent unknown anim {} -> style {} (deferred)", anim, pa.attackStyle);
			}

			pendingOpponentAttacks.add(pa);
			log.debug("Queued OPPONENT_ATTACK: style={} deferred={}", pa.attackStyle, pa.styleDeferred);
		}
	}

	private static final int VENGEANCE_GRAPHIC_ID = 726;

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		if (!inFight || opponent == null)
		{
			return;
		}

		if (event.getActor() == opponent && opponent.getGraphic() == VENGEANCE_GRAPHIC_ID)
		{
			opponentVengeancePending = true;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!inFight)
		{
			return;
		}

		String option = event.getMenuOption();
		if (("Eat".equals(option) || "Drink".equals(option))
			&& event.getMenuAction() == MenuAction.CC_OP
			&& event.getItemId() != -1)
		{
			if (pendingConsumables.isEmpty())
			{
				hpBeforeEating = client.getBoostedSkillLevel(Skill.HITPOINTS);
				ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
				inventorySnapshot = (inv != null) ? inv.getItems().clone() : null;
			}
			// A rapid double/triple-click on the same slot queues multiple menu clicks
			// before the eat is confirmed, but only one eat can actually be processed
			// per slot while unconfirmed. Without this the slot-diff below would
			// confirm every queued click against the same single inventory change.
			if (!pendingConsumableSlots.contains(event.getParam0()))
			{
				pendingConsumables.add(Text.removeTags(event.getMenuTarget()));
				pendingConsumableSlots.add(event.getParam0());
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!inFight)
		{
			return;
		}

		if (event.getContainerId() == InventoryID.INVENTORY.getId())
		{
			inventoryChangedThisTick = true;

			if (!pendingConsumables.isEmpty() && inventorySnapshot != null)
			{
				Item[] newItems = event.getItemContainer().getItems();
				List<String> confirmed = new ArrayList<>();
				for (int i = 0; i < pendingConsumableSlots.size(); i++)
				{
					int slot = pendingConsumableSlots.get(i);
					if (slot >= 0 && slot < inventorySnapshot.length && slot < newItems.length)
					{
						Item before = inventorySnapshot[slot];
						Item after = newItems[slot];
						if (before.getId() != after.getId() || before.getQuantity() != after.getQuantity())
						{
							confirmed.add(pendingConsumables.get(i));
						}
					}
				}
				if (confirmed.size() < pendingConsumables.size())
				{
					log.debug("Slot diff trimmed consumables from {} to {}: {}",
						pendingConsumables.size(), confirmed.size(), confirmed);
					pendingConsumables.clear();
					pendingConsumables.addAll(confirmed);
				}
				inventorySnapshot = null;
				pendingConsumableSlots.clear();
			}
		}

		if (event.getContainerId() == InventoryID.EQUIPMENT.getId())
		{
			equipmentChangedThisTick = true;
		}
	}

	/**
	 * True if a Lightbearer ring is currently equipped, read from the ring slot of the
	 * same equipment snapshot used for gear-switch tracking. Local player only — ring/ammo
	 * are not exposed via the opponent's PlayerComposition.
	 */
	private boolean isLightBearerEquipped()
	{
		if (lastEquipmentItems == null || lastEquipmentItems.length <= SLOT_RING)
		{
			return false;
		}
		return lastEquipmentItems[SLOT_RING].getId() == LIGHTBEARER_ITEM_ID;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!inFight)
		{
			return;
		}

		int ticksIntoCombat = currentTick - fightStartTick;

		if (opponent != null)
		{
			String currentOverhead = headIconName(opponent.getOverheadIcon());
			if (!currentOverhead.equals(lastOverheadPrayer))
			{
				events.add(FightEvent.builder()
					.tick(ticksIntoCombat)
					.type(FightEventType.OVERHEAD_CHANGED)
					.overheadPrayer(currentOverhead)
					.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
					.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
					.build());
				lastOverheadPrayer = currentOverhead;
			}
		}

		// PLAYER_OVERHEAD_CHANGED is intentionally NOT emitted here. Protect prayers are
		// mutually exclusive but implemented client-side as two separate toggles (old one
		// off, new one on), each firing its own onVarbitChanged callback — reading here on
		// every callback records a transient "NONE" between the two toggles of a single
		// direct switch (e.g. RANGE -> MAGIC briefly reads NONE), even though nothing was
		// ever actually unprotected. Settled once per tick in onGameTick instead, see there.

		if (event.getVarpId() == VarPlayer.SPECIAL_ATTACK_PERCENT)
		{
			// Raw value is 0-1000 (1000 = 100%), confirmed from RuneLite's own source
			// (net.runelite.client.plugins.specialcounter divides by 1000.0F to get a
			// 0.0-1.0 fraction). Do not remove this /10 — it was mistakenly removed
			// once already based on a wrong assumption that the raw value was 0-100.
			events.add(FightEvent.builder()
				.tick(ticksIntoCombat)
				.type(FightEventType.SPEC_ENERGY_CHANGED)
				.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
				.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
				.specEnergy(event.getValue() / 10)
				.lightBearerEquipped(isLightBearerEquipped())
				.build());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!inFight)
		{
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		Actor dead = event.getActor();

		String outcome;
		String loser;
		if (dead == localPlayer)
		{
			outcome = "loss";
			loser = localPlayer != null ? localPlayer.getName() : "unknown";
			foodHealingLeft = scanFoodHealing();
		}
		else if (dead == opponent)
		{
			outcome = "win";
			loser = opponent.getName();
		}
		else
		{
			return;
		}

		// Defer to the next GameTick so all pending events on this tick are flushed first.
		pendingFightEnd = true;
		pendingFightOutcome = outcome;
		pendingFightLoser = loser;
	}

	private Player findPlayerByName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (Player p : client.getPlayers())
		{
			if (p != null && name.equals(p.getName()))
			{
				return p;
			}
		}
		return null;
	}

	private void tryStartFight(Player target)
	{
		if (inFight || currentTick < cooldownUntilTick)
		{
			return;
		}

		// Don't start the fight yet; wait for either an attack animation or damage taken.
		// If there's already a pending fight, this click replaces it (last-in-wins).
		if (pendingFightInteraction)
		{
			log.debug("Replacing pending fight: {} -> {} (last-in-wins)", pendingOpponentName, target.getName());
		}

		pendingFightInteraction = true;
		pendingOpponent = target;
		pendingOpponentName = target.getName();
		pendingFightStartTick = currentTick;
		pendingFightStartTime = Instant.now();
		pendingSpecEnergy = client.getVarpValue(VarPlayer.SPECIAL_ATTACK_PERCENT) / 10;
		pendingLightBearerEquipped = isLightBearerEquipped();

		log.debug("Pending fight: {} (click-to-attack detected, awaiting confirmation)", target.getName());
	}

	/**
	 * Confirm a pending fight by transitioning to active fight state.
	 * Called when player attack animation fires or player takes damage.
	 */
	private void confirmPendingFight()
	{
		if (!pendingFightInteraction || pendingOpponent == null)
		{
			return;
		}

		log.debug("Fight confirmed: {} (attack animation or damage received)", pendingOpponentName);

		opponent = pendingOpponent;
		opponentName = pendingOpponentName;
		inFight = true;
		fightStartTick = pendingFightStartTick;
		fightStartTime = pendingFightStartTime;
		events.clear();

		lastOverheadPrayer = headIconName(opponent.getOverheadIcon());
		lastMyOverheadPrayer = localOverheadPrayer();
		foodHealingLeft = -1;
		pendingConsumables.clear();
		pendingConsumableSlots.clear();
		inventorySnapshot = null;
		hpBeforeEating = -1;
		inventoryChangedThisTick = false;
		pendingConsumablesAge = 0;
		opponentLastAttackStyle = null;
		opponentVengeancePending = false;
		lastPlayerAttackTick = -MIN_ATTACK_COOLDOWN_TICKS;
		opponentMissingSinceTick = -1;
		pendingOpponentAttacks.clear();
		pendingPlayerAttacks.clear();
		equipmentChangedThisTick = false;
		ItemContainer startEq = client.getItemContainer(InventoryID.EQUIPMENT);
		lastEquipmentItems = startEq != null ? startEq.getItems().clone() : null;
		optimalBonuses = gearAnalyzer.getOptimalBonuses();
		optimalDefenseBonuses = gearAnalyzer.getOptimalDefenseBonuses();
		StatBoosts inventoryOptimal = PotionBoosts.calcOptimal(
			client.getItemContainer(InventoryID.INVENTORY), itemManager, client);
		// If the player is already potted (pot consumed before the fight), their current
		// boosted level may exceed what remaining inventory potions project. Take the max
		// so effectiveness never exceeds 100% at fight start.
		optimalStatBoosts = new StatBoosts(
			Math.max(inventoryOptimal.getAttack(),   client.getBoostedSkillLevel(Skill.ATTACK)),
			Math.max(inventoryOptimal.getStrength(), client.getBoostedSkillLevel(Skill.STRENGTH)),
			Math.max(inventoryOptimal.getRanged(),   client.getBoostedSkillLevel(Skill.RANGED)),
			Math.max(inventoryOptimal.getMagic(),    client.getBoostedSkillLevel(Skill.MAGIC))
		);
		baseStatBoosts = new StatBoosts(
			client.getRealSkillLevel(Skill.ATTACK),
			client.getRealSkillLevel(Skill.STRENGTH),
			client.getRealSkillLevel(Skill.RANGED),
			client.getRealSkillLevel(Skill.MAGIC)
		);

		// Clear pending state
		pendingFightInteraction = false;
		pendingOpponent = null;
		pendingOpponentName = null;

		Player localPlayer = client.getLocalPlayer();
		String localName = localPlayer != null ? localPlayer.getName() : "unknown";

		events.add(FightEvent.builder()
			.tick(0)
			.type(FightEventType.FIGHT_START)
			.playerHp(client.getBoostedSkillLevel(Skill.HITPOINTS))
			.playerPrayer(client.getBoostedSkillLevel(Skill.PRAYER))
			.specEnergy(pendingSpecEnergy)
			.lightBearerEquipped(pendingLightBearerEquipped)
			.maxHp(client.getRealSkillLevel(Skill.HITPOINTS))
			.build());


		log.debug("Fight started: {} vs {}", localName, opponentName);
	}

	private void endFight(String outcome)
	{
		// Scan food now for wins/unknowns. For losses it was already captured in
		// onActorDeath before the death screen could clear the inventory.
		if (foodHealingLeft < 0)
		{
			foodHealingLeft = scanFoodHealing();
		}

		Player localPlayer = client.getLocalPlayer();
		String localName = localPlayer != null ? localPlayer.getName() : "unknown";
		String resolvedOpponentName = opponentName != null ? opponentName : "unknown";

		FightData fightData = new FightData(
			localName,
			resolvedOpponentName,
			outcome,
			fightStartTime,
			Instant.now(),
			currentTick - fightStartTick,
			new ArrayList<>(events),
			optimalBonuses,
			optimalDefenseBonuses,
			optimalStatBoosts,
			baseStatBoosts,
			foodHealingLeft
		);

		log.debug("Fight complete: {} vs {}, outcome={}, ticks={}, events={}",
			localName, resolvedOpponentName, outcome, fightData.getTotalTicks(), fightData.getEvents().size());

		inFight = false;
		opponent = null;
		opponentName = null;
		events.clear();
		optimalBonuses = null;
		optimalDefenseBonuses = null;
		optimalStatBoosts = null;
		baseStatBoosts = null;
		cooldownUntilTick = currentTick + FIGHT_COOLDOWN_TICKS;
		pendingFightEnd = false;
		pendingFightOutcome = null;
		pendingFightLoser = null;
		opponentMissingSinceTick = -1;
		foodHealingLeft = -1;
		lastEquipmentItems = null;
		equipmentChangedThisTick = false;

		if (fightCompleteListener != null)
		{
			fightCompleteListener.onFightComplete(fightData);
		}
	}

	private StatBoosts currentStatBoosts()
	{
		return new StatBoosts(
			client.getBoostedSkillLevel(Skill.ATTACK),
			client.getBoostedSkillLevel(Skill.STRENGTH),
			client.getBoostedSkillLevel(Skill.RANGED),
			client.getBoostedSkillLevel(Skill.MAGIC)
		);
	}

	private int scanFoodHealing()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		if (inv == null)
		{
			return 0;
		}
		int baseMaxHp = client.getRealSkillLevel(Skill.HITPOINTS);
		int total = 0;
		for (Item item : inv.getItems())
		{
			if (item.getId() == -1)
			{
				continue;
			}
			String name = itemManager.getItemComposition(item.getId()).getName();
			total += FoodHealAmounts.calcItemHeal(name, item.getQuantity(), baseMaxHp);
		}
		log.debug("Food healing left: {} hp", total);
		return total;
	}

	private static String headIconName(HeadIcon icon)
	{
		return icon != null ? icon.name() : "NONE";
	}

	/**
	 * Returns the local player's active overhead protection prayer as a string.
	 * Reads from prayer varbits rather than PlayerComposition so the result is
	 * accurate within the same tick the prayer was toggled (getOverheadIcon() on
	 * the local player can lag by one tick due to PlayerComposition update timing).
	 */
	private String localOverheadPrayer()
	{
		if (client.isPrayerActive(Prayer.PROTECT_FROM_MELEE))    return "MELEE";
		if (client.isPrayerActive(Prayer.PROTECT_FROM_MISSILES)) return "RANGED";
		if (client.isPrayerActive(Prayer.PROTECT_FROM_MAGIC))    return "MAGIC";
		return "NONE";
	}

	private static boolean overheadCorrect(String myOverhead, String opponentStyle)
	{
		if (opponentStyle == null || myOverhead == null || "NONE".equals(myOverhead))
		{
			return false;
		}
		switch (opponentStyle)
		{
			case "melee":  return "MELEE".equals(myOverhead);
			case "ranged": return "RANGED".equals(myOverhead);
			case "magic":  return "MAGIC".equals(myOverhead);
			default:       return false;
		}
	}

	private static boolean isAttackOffPrayer(String attackStyle, String opponentOverhead)
	{
		if (attackStyle == null)
		{
			return false;
		}
		switch (attackStyle)
		{
			case "melee":  return !"MELEE".equals(opponentOverhead);
			case "ranged": return !"RANGED".equals(opponentOverhead);
			case "magic":  return !"MAGIC".equals(opponentOverhead);
			default:       return false;
		}
	}

	/**
	 * Returns the name of the active offensive prayer matching the given attack style,
	 * or null if none is active. Checked strongest-first so the best active prayer wins.
	 */
	private String activeOffensivePrayer(String attackStyle)
	{
		Prayer[] prayers;
		switch (attackStyle)
		{
			case "melee":
				prayers = new Prayer[]{
					Prayer.PIETY, Prayer.CHIVALRY,
					Prayer.ULTIMATE_STRENGTH, Prayer.SUPERHUMAN_STRENGTH, Prayer.BURST_OF_STRENGTH
				};
				break;
			case "ranged":
				prayers = new Prayer[]{
					Prayer.RIGOUR, Prayer.DEADEYE,
					Prayer.EAGLE_EYE, Prayer.HAWK_EYE, Prayer.SHARP_EYE
				};
				break;
			case "magic":
				prayers = new Prayer[]{
					Prayer.AUGURY, Prayer.MYSTIC_VIGOUR,
					Prayer.MYSTIC_MIGHT, Prayer.MYSTIC_LORE, Prayer.MYSTIC_WILL
				};
				break;
			default:
				return null;
		}
		for (Prayer p : prayers)
		{
			if (client.isPrayerActive(p))
			{
				return p.name();
			}
		}
		return null;
	}
}

package com.aipvpcoach;

import lombok.Value;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Aggregated statistics derived from a completed {@link FightData}.
 * Computed once after a fight ends; suitable for both the RuneLite overlay
 * snapshot and as pre-aggregated context in the LLM request payload.
 */
@Value
public class FightSummary
{
	String outcome;
	int durationTicks;

	int totalDamageDealt;
	int totalDamageTaken;

	/**
	 * Hits where we knew the opponent's attack style (i.e. they had animated
	 * before the hitsplat arrived). Only these are used for overhead accuracy.
	 */
	int overheadCheckableHits;

	/** Of the checkable hits, how many had the correct overhead active. */
	int overheadCorrectHits;

	/** Total individual items consumed (sum across all FOOD_EATEN events). */
	int foodEaten;
	int specsUsed;

	/**
	 * Player's own ATTACK_ATTEMPTED events broken down by style.
	 * Keys: "melee", "ranged", "magic". Missing key means zero attacks.
	 */
	Map<String, Integer> attackStyleCounts;

	/** How many of our ATTACK_ATTEMPTED events landed while the opponent lacked the correct overhead. */
	int attacksOffPrayer;

	/** Total HP wasted to overeating across the fight (excludes boost-item combos). */
	int totalHpWasted;

	/** Total healing value of food remaining in inventory at fight end. */
	int foodHealingLeft;

	/** Attack attempts where the relevant stat was above the player's real level (potted). */
	int attacksPotted;
	/** Attack attempts where the relevant stat equalled the player's real level (unpotted). */
	int attacksUnpotted;
	/** Attack attempts where the relevant stat was below the player's real level (brewed down). */
	int attacksBrewed;

	/**
	 * Average offensive gear effectiveness per attack style (0â€“100).
	 * For melee: average of the primary attack bonus (stab/slash/crush based on weapon) and strength.
	 * For ranged: average of ranged attack and ranged strength.
	 * For magic: average of magic attack and magic damage.
	 * Missing key means no attacks in that style.
	 */
	Map<String, Integer> avgOffensiveGearEff;

	/**
	 * Average offensive stat effectiveness per attack style (0â€“100).
	 * For melee: average of attack and strength levels vs optimal.
	 * For ranged/magic: single stat vs optimal.
	 * Missing key means no attacks in that style.
	 */
	Map<String, Integer> avgOffensiveStatEff;

	/**
	 * Average defensive tank effectiveness per incoming attack style (0â€“100).
	 * For melee: uses dStab/dSlash/dCrush matched to the opponent's weapon type;
	 *            falls back to the average of all three when weapon is unmapped.
	 * For ranged: dRange. For magic: dMagic.
	 * Missing key means no incoming attacks in that style.
	 */
	Map<String, Integer> avgDefensiveTankEff;

	// -------------------------------------------------------------------------
	// Derived helpers
	// -------------------------------------------------------------------------

	/** 0â€“100 percentage; returns 0 if no checkable hits. */
	public int overheadCorrectPct()
	{
		if (overheadCheckableHits == 0)
		{
			return 0;
		}
		return (int) Math.round(100.0 * overheadCorrectHits / overheadCheckableHits);
	}

	/** Total melee + ranged + magic attack attempts. */
	public int totalAttacks()
	{
		return attackStyleCounts.values().stream().mapToInt(Integer::intValue).sum();
	}

	/** 0â€“100 percentage of attacks that were off prayer; returns 0 if no attacks. */
	public int attacksOffPrayerPct()
	{
		int total = totalAttacks();
		if (total == 0)
		{
			return 0;
		}
		return (int) Math.round(100.0 * attacksOffPrayer / total);
	}

	// -------------------------------------------------------------------------
	// Factory
	// -------------------------------------------------------------------------

	public static FightSummary from(FightData fight)
	{
		int damageDealt = 0;
		int damageTaken = 0;
		int overheadCheckable = 0;
		int overheadCorrect = 0;
		int foodEaten = 0;
		int specsUsed = 0;
		int attacksOffPrayer = 0;
		int totalHpWasted = 0;
		int attacksPotted = 0;
		int attacksUnpotted = 0;
		int attacksBrewed = 0;
		Map<String, Integer> attackStyles = new LinkedHashMap<>();
		StatBoosts base = fight.getBaseStatBoosts();

		GearBonuses optimal = fight.getOptimalBonuses();
		DefenseBonuses optimalDef = fight.getOptimalDefenseBonuses();
		StatBoosts optimalStat = fight.getOptimalStatBoosts();

		Map<String, Long> offGearSum = new LinkedHashMap<>();
		Map<String, Integer> offGearCount = new LinkedHashMap<>();
		Map<String, Long> offStatSum = new LinkedHashMap<>();
		Map<String, Integer> offStatCount = new LinkedHashMap<>();
		Map<String, Long> defTankSum = new LinkedHashMap<>();
		Map<String, Integer> defTankCount = new LinkedHashMap<>();

		for (FightEvent e : fight.getEvents())
		{
			switch (e.getType())
			{
				case DAMAGE_DEALT:
					damageDealt += e.getAmount();
					break;

				case DAMAGE_TAKEN:
					damageTaken += e.getAmount();
					break;

				case OPPONENT_ATTACK:
					overheadCheckable++;
					if (e.isOverheadCorrect())
					{
						overheadCorrect++;
					}
					if (optimalDef != null && e.getDefBonuses() != null && e.getOpponentAttackStyle() != null)
					{
						String oppStyle = e.getOpponentAttackStyle();
						Map<String, Integer> defEff = e.getDefBonuses().effectiveness(optimalDef);
						int tankEffPct;
						switch (oppStyle)
						{
							case "melee":
								String meleeSubStyle = MeleeWeaponStyle.resolve(e.getOpponentWeaponId(), null);
								if (meleeSubStyle != null)
								{
									String defKey = meleeSubStyleToDefKey(meleeSubStyle);
									tankEffPct = defEff.getOrDefault(defKey, 0);
								}
								else
								{
									// Weapon not mapped: average all three melee def values
									int ds = defEff.getOrDefault("dStab", 0);
									int dl = defEff.getOrDefault("dSlash", 0);
									int dc = defEff.getOrDefault("dCrush", 0);
									tankEffPct = (ds + dl + dc) / 3;
								}
								break;
							case "ranged":
								tankEffPct = defEff.getOrDefault("dRange", 0);
								break;
							case "magic":
								tankEffPct = defEff.getOrDefault("dMagic", 0);
								break;
							default:
								tankEffPct = -1;
								break;
						}
						if (tankEffPct >= 0)
						{
							defTankSum.merge(oppStyle, (long) tankEffPct, Long::sum);
							defTankCount.merge(oppStyle, 1, Integer::sum);
						}
					}
					break;

				case FOOD_EATEN:
					foodEaten += e.getConsumedItems().size();
					int wasted = FoodHealAmounts.calcWasted(
						e.getConsumedItems(), e.getHpBeforeEating(), e.getMaxHp());
					if (wasted > 0)
					{
						totalHpWasted += wasted;
					}
					break;

				case ATTACK_ATTEMPTED:
					if (e.isSpecialAttack())
					{
						specsUsed++;
					}
					String style = e.getAttackStyle();
					if (style != null)
					{
						attackStyles.merge(style, 1, Integer::sum);
					}
					if (e.isAttackOffPrayer())
					{
						attacksOffPrayer++;
					}
					if (base != null && e.getStatBoosts() != null && style != null)
					{
						int current, baseVal;
						switch (style)
						{
							case "melee":
								current = e.getStatBoosts().getStrength();
								baseVal = base.getStrength();
								break;
							case "ranged":
								current = e.getStatBoosts().getRanged();
								baseVal = base.getRanged();
								break;
							case "magic":
								current = e.getStatBoosts().getMagic();
								baseVal = base.getMagic();
								break;
							default:
								current = -1;
								baseVal = -1;
								break;
						}
						if (current > baseVal)       attacksPotted++;
						else if (current == baseVal) attacksUnpotted++;
						else if (current >= 0)       attacksBrewed++;
					}
					// Offensive gear effectiveness â€” excluded for spec attacks since the spec
					// weapon is an intentional choice, not a reflection of gear quality.
					if (!e.isSpecialAttack() && optimal != null && e.getGearBonuses() != null && style != null)
					{
						Map<String, Integer> gearEff = e.getGearBonuses().effectiveness(optimal);
						int gearEffPct;
						switch (style)
						{
							case "melee":
								String subStyle = MeleeWeaponStyle.resolve(e.getPlayerWeaponId(), e.getGearBonuses());
								if (subStyle == null) subStyle = "slash";
								int atkEff = gearEff.getOrDefault(subStyle, 0);
								int strEff = gearEff.getOrDefault("str", 0);
								gearEffPct = (atkEff + strEff) / 2;
								break;
							case "ranged":
								gearEffPct = (gearEff.getOrDefault("ranged", 0) + gearEff.getOrDefault("rstr", 0)) / 2;
								break;
							case "magic":
								gearEffPct = (gearEff.getOrDefault("magic", 0) + gearEff.getOrDefault("mdmg", 0)) / 2;
								break;
							default:
								gearEffPct = -1;
								break;
						}
						if (gearEffPct >= 0)
						{
							offGearSum.merge(style, (long) gearEffPct, Long::sum);
							offGearCount.merge(style, 1, Integer::sum);
						}
					}
					// Offensive stat effectiveness
					if (optimalStat != null && e.getStatBoosts() != null && style != null)
					{
						Map<String, Integer> statEff = e.getStatBoosts().effectiveness(optimalStat, style);
						int statEffPct;
						switch (style)
						{
							case "melee":
								statEffPct = (statEff.getOrDefault("str", 0) + statEff.getOrDefault("att", 0)) / 2;
								break;
							case "ranged":
								statEffPct = statEff.getOrDefault("range", 0);
								break;
							case "magic":
								statEffPct = statEff.getOrDefault("magic", 0);
								break;
							default:
								statEffPct = -1;
								break;
						}
						if (statEffPct >= 0)
						{
							// Cap at 100 â€” re-potting above the fight-start optimal is fine but
							// an effectiveness summary shouldn't exceed 100%.
							offStatSum.merge(style, (long) Math.min(statEffPct, 100), Long::sum);
							offStatCount.merge(style, 1, Integer::sum);
						}
					}
					break;

				default:
					break;
			}
		}

		return new FightSummary(
			fight.getOutcome(),
			fight.getTotalTicks(),
			damageDealt,
			damageTaken,
			overheadCheckable,
			overheadCorrect,
			foodEaten,
			specsUsed,
			Collections.unmodifiableMap(attackStyles),
			attacksOffPrayer,
			totalHpWasted,
			fight.getFoodHealingLeft(),
			attacksPotted,
			attacksUnpotted,
			attacksBrewed,
			averageMap(offGearSum, offGearCount),
			averageMap(offStatSum, offStatCount),
			averageMap(defTankSum, defTankCount)
		);
	}

	private static Map<String, Integer> averageMap(Map<String, Long> sums, Map<String, Integer> counts)
	{
		Map<String, Integer> result = new LinkedHashMap<>();
		for (String key : sums.keySet())
		{
			int count = counts.getOrDefault(key, 0);
			if (count > 0)
			{
				result.put(key, (int) Math.round((double) sums.get(key) / count));
			}
		}
		return Collections.unmodifiableMap(result);
	}

	private static String meleeSubStyleToDefKey(String subStyle)
	{
		switch (subStyle)
		{
			case "stab":  return "dStab";
			case "slash": return "dSlash";
			case "crush": return "dCrush";
			default:      return "dSlash";
		}
	}
}

package com.aipvpcoach;

import java.util.HashMap;
import java.util.Map;

/**
 * Known fixed heal amounts and boost-item flags for consumables.
 *
 * "Boost items" (Saradomin brew, Anglerfish) temporarily raise the HP cap
 * above base max, so a simple overeat calculation does not apply to them.
 * When a boost item appears in a combo, overeat calculation is skipped for
 * the whole event to avoid silently wrong results.
 *
 * Add entries here as item names are confirmed in-game.
 * Names must match exactly what RuneLite returns after stripping color tags
 * (case-insensitive matching is applied at lookup time).
 */
public final class FoodHealAmounts
{
	private FoodHealAmounts() {}

	/** Maps lowercase item name â†’ fixed heal amount. */
	private static final Map<String, Integer> HEAL_AMOUNTS = new HashMap<>();

	static
	{
		// ---- Common PvP food ----
		HEAL_AMOUNTS.put("marlin",             24);
		HEAL_AMOUNTS.put("dark crab",         22);
		HEAL_AMOUNTS.put("manta ray",          22);
		HEAL_AMOUNTS.put("tuna potato",        22);
		HEAL_AMOUNTS.put("sea turtle",         21);
		HEAL_AMOUNTS.put("shark",              20);
		HEAL_AMOUNTS.put("halibut",            20);
		HEAL_AMOUNTS.put("cooked karambwan",   18);
		HEAL_AMOUNTS.put("monkfish",           16);
		HEAL_AMOUNTS.put("swordfish",          14);
		HEAL_AMOUNTS.put("bass",               13);
		HEAL_AMOUNTS.put("lobster",            12);
		HEAL_AMOUNTS.put("tuna",              10);
		HEAL_AMOUNTS.put("salmon",             9);
		HEAL_AMOUNTS.put("trout",              7);
		HEAL_AMOUNTS.put("cod",               7);
		HEAL_AMOUNTS.put("pike",               8);
		HEAL_AMOUNTS.put("mackerel",           6);
		HEAL_AMOUNTS.put("herring",            5);
		HEAL_AMOUNTS.put("sardine",            4);
		HEAL_AMOUNTS.put("shrimps",            3);
		HEAL_AMOUNTS.put("anchovies",          1);
	}

	/**
	 * Returns the fixed heal amount for the given item, or -1 if unknown.
	 * Boost items (which can raise the HP cap) return -1 intentionally.
	 */
	public static int getHealAmount(String itemName)
	{
		if (itemName == null)
		{
			return -1;
		}
		return HEAL_AMOUNTS.getOrDefault(itemName.toLowerCase().trim(), -1);
	}

	/**
	 * Returns true if this item can temporarily raise HP above base max HP.
	 * Overeat simulation is skipped for combos containing a boost item.
	 */
	public static boolean isBoostItem(String itemName)
	{
		if (itemName == null)
		{
			return false;
		}
		String lower = itemName.toLowerCase().trim();
		return lower.startsWith("saradomin brew")
			|| lower.equals("anglerfish");
	}

	/**
	 * Returns the total healing value for a single inventory slot.
	 *
	 * Handles regular food (fixed heal * quantity), Saradomin brews (dose-based,
	 * requires baseMaxHp), and stacked items (e.g. karambwans).
	 * Returns 0 for items not recognised as food.
	 *
	 * @param itemName  display name of the item (color tags already stripped)
	 * @param quantity  stack size from the inventory slot
	 * @param baseMaxHp used only for brew heal calculation
	 */
	public static int calcItemHeal(String itemName, int quantity, int baseMaxHp)
	{
		if (itemName == null || quantity <= 0)
		{
			return 0;
		}

		String lower = itemName.toLowerCase().trim();

		// Saradomin brew: heals floor(baseMaxHp * 0.15) + 2 per dose.
		// Item name encodes the remaining doses, e.g. "Saradomin brew(4)".
		if (lower.startsWith("saradomin brew"))
		{
			int doses = extractDose(lower);
			int healPerDose = (int) Math.floor(baseMaxHp * 0.15) + 2;
			return doses * healPerDose * quantity;
		}

		int healPerItem = getHealAmount(itemName);
		if (healPerItem > 0)
		{
			return healPerItem * quantity;
		}

		return 0;
	}

	/** Extracts the numeric dose from a name like "saradomin brew(4)". Returns 1 if not found. */
	private static int extractDose(String lowerName)
	{
		int open = lowerName.lastIndexOf('(');
		int close = lowerName.lastIndexOf(')');
		if (open >= 0 && close > open)
		{
			try
			{
				return Integer.parseInt(lowerName.substring(open + 1, close).trim());
			}
			catch (NumberFormatException ignored)
			{
			}
		}
		return 1;
	}

	/**
	 * Simulates sequential eating and returns total HP wasted against the given
	 * base max HP. Returns -1 if any item in the list is a boost item (overeat
	 * calculation does not apply) or if hpBefore is unknown (< 0).
	 *
	 * Items not in the lookup table are skipped (treated as zero heal for
	 * waste purposes) and noted in the returned value only when wasted > 0.
	 */
	public static int calcWasted(java.util.List<String> items, int hpBefore, int maxHp)
	{
		if (hpBefore < 0)
		{
			return -1;
		}

		for (String item : items)
		{
			if (isBoostItem(item))
			{
				return -1;
			}
		}

		int currentHp = hpBefore;
		int wasted = 0;

		for (String item : items)
		{
			int heal = getHealAmount(item);
			if (heal < 0)
			{
				// Unknown item â€” skip waste contribution but don't abort.
				continue;
			}
			int potential = currentHp + heal;
			if (potential > maxHp)
			{
				wasted += potential - maxHp;
				currentHp = maxHp;
			}
			else
			{
				currentHp = potential;
			}
		}

		return wasted;
	}
}

package com.aipvpcoach;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
@Singleton
public class GearAnalyzer
{
	private static final int SLOT_WEAPON = 3;
	private static final int SLOT_SHIELD = 5;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	/**
	 * Returns the bonuses from the player's currently equipped items.
	 */
	public GearBonuses getCurrentBonuses()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return zero();
		}

		int aStab = 0, aSlash = 0, aCrush = 0, aMagic = 0, aRange = 0;
		int sStr = 0, sRstr = 0;
		float sMdmg = 0f;

		for (Item item : equipment.getItems())
		{
			if (item == null || item.getId() == -1)
			{
				continue;
			}
			ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats == null || !stats.isEquipable())
			{
				continue;
			}
			ItemEquipmentStats eq = stats.getEquipment();
			if (eq == null)
			{
				continue;
			}
			aStab += eq.getAstab();
			aSlash += eq.getAslash();
			aCrush += eq.getAcrush();
			aMagic += eq.getAmagic();
			aRange += eq.getArange();
			sStr += eq.getStr();
			sRstr += eq.getRstr();
			sMdmg += eq.getMdmg();
		}

		return new GearBonuses(aStab, aSlash, aCrush, aMagic, aRange, sStr, sRstr, sMdmg);
	}

	/**
	 * Returns the defensive bonuses from the player's currently equipped items.
	 */
	public DefenseBonuses getCurrentDefenseBonuses()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return new DefenseBonuses(0, 0, 0, 0, 0);
		}

		int dStab = 0, dSlash = 0, dCrush = 0, dRange = 0, dMagic = 0;

		for (Item item : equipment.getItems())
		{
			if (item == null || item.getId() == -1)
			{
				continue;
			}
			ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats == null || !stats.isEquipable())
			{
				continue;
			}
			ItemEquipmentStats eq = stats.getEquipment();
			if (eq == null)
			{
				continue;
			}
			dStab  += eq.getDstab();
			dSlash += eq.getDslash();
			dCrush += eq.getDcrush();
			dRange += eq.getDrange();
			dMagic += eq.getDmagic();
		}

		return new DefenseBonuses(dStab, dSlash, dCrush, dRange, dMagic);
	}

	/**
	 * Returns the best possible bonuses the player could achieve using items
	 * currently in their equipment and inventory, computed independently per style.
	 */
	public GearBonuses getOptimalBonuses()
	{
		// Collect all equipable items from equipment + inventory
		Map<Integer, List<ItemEquipmentStats>> bySlot = new HashMap<>();
		collectItems(bySlot, client.getItemContainer(InventoryID.EQUIPMENT));
		collectItems(bySlot, client.getItemContainer(InventoryID.INVENTORY));

		List<ItemEquipmentStats> weapons = bySlot.getOrDefault(SLOT_WEAPON, new ArrayList<>());
		List<ItemEquipmentStats> shields = bySlot.getOrDefault(SLOT_SHIELD, new ArrayList<>());

		// For each bonus style, compute the optimal sum
		int aStab = optimalAttackStyle(bySlot, weapons, shields, BonusType.STAB);
		int aSlash = optimalAttackStyle(bySlot, weapons, shields, BonusType.SLASH);
		int aCrush = optimalAttackStyle(bySlot, weapons, shields, BonusType.CRUSH);
		int aMagic = optimalAttackStyle(bySlot, weapons, shields, BonusType.MAGIC);
		int aRange = optimalAttackStyle(bySlot, weapons, shields, BonusType.RANGED);
		int sStr = optimalStrengthStyle(bySlot, weapons, shields, BonusType.STR);
		int sRstr = optimalStrengthStyle(bySlot, weapons, shields, BonusType.RSTR);
		float sMdmg = optimalMdmg(bySlot, weapons, shields);

		return new GearBonuses(aStab, aSlash, aCrush, aMagic, aRange, sStr, sRstr, sMdmg);
	}

	/**
	 * Returns the best possible defensive bonuses the player could achieve using items
	 * currently in their equipment and inventory, computed independently per style.
	 * Each style (stab/slash/crush/range/magic) represents a separate optimal loadout.
	 */
	public DefenseBonuses getOptimalDefenseBonuses()
	{
		Map<Integer, List<ItemEquipmentStats>> bySlot = new HashMap<>();
		collectItems(bySlot, client.getItemContainer(InventoryID.EQUIPMENT));
		collectItems(bySlot, client.getItemContainer(InventoryID.INVENTORY));

		List<ItemEquipmentStats> weapons = bySlot.getOrDefault(SLOT_WEAPON, new ArrayList<>());
		List<ItemEquipmentStats> shields = bySlot.getOrDefault(SLOT_SHIELD, new ArrayList<>());

		int dStab  = optimalAttackStyle(bySlot, weapons, shields, BonusType.DSTAB);
		int dSlash = optimalAttackStyle(bySlot, weapons, shields, BonusType.DSLASH);
		int dCrush = optimalAttackStyle(bySlot, weapons, shields, BonusType.DCRUSH);
		int dRange = optimalAttackStyle(bySlot, weapons, shields, BonusType.DRANGE);
		int dMagic = optimalAttackStyle(bySlot, weapons, shields, BonusType.DMAGIC);

		return new DefenseBonuses(dStab, dSlash, dCrush, dRange, dMagic);
	}

	private void collectItems(Map<Integer, List<ItemEquipmentStats>> bySlot, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() == -1)
			{
				continue;
			}
			ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats == null || !stats.isEquipable())
			{
				continue;
			}
			ItemEquipmentStats eq = stats.getEquipment();
			if (eq == null)
			{
				continue;
			}
			bySlot.computeIfAbsent(eq.getSlot(), k -> new ArrayList<>()).add(eq);
		}
	}

	private enum BonusType
	{
		STAB, SLASH, CRUSH, MAGIC, RANGED, STR, RSTR,
		DSTAB, DSLASH, DCRUSH, DRANGE, DMAGIC
	}

	private int getBonusInt(ItemEquipmentStats eq, BonusType type)
	{
		switch (type)
		{
			case STAB:   return eq.getAstab();
			case SLASH:  return eq.getAslash();
			case CRUSH:  return eq.getAcrush();
			case MAGIC:  return eq.getAmagic();
			case RANGED: return eq.getArange();
			case STR:    return eq.getStr();
			case RSTR:   return eq.getRstr();
			case DSTAB:  return eq.getDstab();
			case DSLASH: return eq.getDslash();
			case DCRUSH: return eq.getDcrush();
			case DRANGE: return eq.getDrange();
			case DMAGIC: return eq.getDmagic();
			default:     return 0;
		}
	}

	/**
	 * Computes optimal attack-style bonus across all slots, handling the 2H/shield conflict.
	 */
	private int optimalAttackStyle(Map<Integer, List<ItemEquipmentStats>> bySlot,
		List<ItemEquipmentStats> weapons, List<ItemEquipmentStats> shields, BonusType type)
	{
		// Best 1H weapon score
		int best1H = Integer.MIN_VALUE;
		for (ItemEquipmentStats w : weapons)
		{
			if (!w.isTwoHanded())
			{
				int v = getBonusInt(w, type);
				if (v > best1H)
				{
					best1H = v;
				}
			}
		}
		if (best1H == Integer.MIN_VALUE)
		{
			best1H = 0;
		}

		// Best shield score
		int bestShield = 0;
		for (ItemEquipmentStats s : shields)
		{
			int v = getBonusInt(s, type);
			if (v > bestShield)
			{
				bestShield = v;
			}
		}

		// Best 2H weapon score
		int best2H = Integer.MIN_VALUE;
		for (ItemEquipmentStats w : weapons)
		{
			if (w.isTwoHanded())
			{
				int v = getBonusInt(w, type);
				if (v > best2H)
				{
					best2H = v;
				}
			}
		}
		if (best2H == Integer.MIN_VALUE)
		{
			best2H = 0;
		}

		int combo1H = best1H + bestShield;
		int combo2H = best2H; // no shield

		int weaponShieldBest = Math.max(combo1H, combo2H);

		// Sum contributions from all non-weapon, non-shield slots
		int otherSum = 0;
		for (Map.Entry<Integer, List<ItemEquipmentStats>> entry : bySlot.entrySet())
		{
			int slot = entry.getKey();
			if (slot == SLOT_WEAPON || slot == SLOT_SHIELD)
			{
				continue;
			}
			int best = Integer.MIN_VALUE;
			for (ItemEquipmentStats eq : entry.getValue())
			{
				int v = getBonusInt(eq, type);
				if (v > best)
				{
					best = v;
				}
			}
			if (best != Integer.MIN_VALUE)
			{
				otherSum += best;
			}
		}

		return weaponShieldBest + otherSum;
	}

	/**
	 * Computes optimal integer strength-style bonus (melee str or ranged str).
	 */
	private int optimalStrengthStyle(Map<Integer, List<ItemEquipmentStats>> bySlot,
		List<ItemEquipmentStats> weapons, List<ItemEquipmentStats> shields, BonusType type)
	{
		// Same logic as attack styles
		return optimalAttackStyle(bySlot, weapons, shields, type);
	}

	/**
	 * Computes optimal magic damage % bonus.
	 */
	private float optimalMdmg(Map<Integer, List<ItemEquipmentStats>> bySlot,
		List<ItemEquipmentStats> weapons, List<ItemEquipmentStats> shields)
	{
		float best1H = -Float.MAX_VALUE;
		for (ItemEquipmentStats w : weapons)
		{
			if (!w.isTwoHanded())
			{
				float v = w.getMdmg();
				if (v > best1H)
				{
					best1H = v;
				}
			}
		}
		if (best1H == -Float.MAX_VALUE)
		{
			best1H = 0f;
		}

		float bestShield = 0f;
		for (ItemEquipmentStats s : shields)
		{
			float v = s.getMdmg();
			if (v > bestShield)
			{
				bestShield = v;
			}
		}

		float best2H = -Float.MAX_VALUE;
		for (ItemEquipmentStats w : weapons)
		{
			if (w.isTwoHanded())
			{
				float v = w.getMdmg();
				if (v > best2H)
				{
					best2H = v;
				}
			}
		}
		if (best2H == -Float.MAX_VALUE)
		{
			best2H = 0f;
		}

		float combo1H = best1H + bestShield;
		float combo2H = best2H;
		float weaponShieldBest = Math.max(combo1H, combo2H);

		float otherSum = 0f;
		for (Map.Entry<Integer, List<ItemEquipmentStats>> entry : bySlot.entrySet())
		{
			int slot = entry.getKey();
			if (slot == SLOT_WEAPON || slot == SLOT_SHIELD)
			{
				continue;
			}
			float best = -Float.MAX_VALUE;
			for (ItemEquipmentStats eq : entry.getValue())
			{
				float v = eq.getMdmg();
				if (v > best)
				{
					best = v;
				}
			}
			if (best != -Float.MAX_VALUE)
			{
				otherSum += best;
			}
		}

		return weaponShieldBest + otherSum;
	}

	/**
	 * Resolves the melee sub-style ("stab", "slash", or "crush") for a weapon ID.
	 * Checks the MeleeWeaponStyle map first; falls back to the weapon's own highest
	 * attack bonus via ItemManager. Returns null if the weapon ID is invalid.
	 */
	public String getMeleeSubStyle(int weaponId)
	{
		String mapped = MeleeWeaponStyle.resolve(weaponId, null);
		if (mapped != null)
		{
			return mapped;
		}
		if (weaponId <= 0)
		{
			return null;
		}
		ItemStats stats = itemManager.getItemStats(weaponId);
		if (stats == null || !stats.isEquipable())
		{
			return null;
		}
		ItemEquipmentStats eq = stats.getEquipment();
		if (eq == null)
		{
			return null;
		}
		int stab  = eq.getAstab();
		int slash = eq.getAslash();
		int crush = eq.getAcrush();
		if (stab >= slash && stab >= crush) return "stab";
		if (slash >= crush)                 return "slash";
		return "crush";
	}

	/**
	 * Returns the item ID of the player's currently equipped weapon, or -1 if none.
	 */
	public int getPlayerWeaponId()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return -1;
		}
		Item[] items = equipment.getItems();
		if (items.length <= SLOT_WEAPON)
		{
			return -1;
		}
		Item weapon = items[SLOT_WEAPON];
		return (weapon == null || weapon.getId() == -1) ? -1 : weapon.getId();
	}

	/**
	 * Returns "magic", "ranged", or "melee" based on the equipped weapon's attack bonuses.
	 * Magic and ranged weapons have a positive bonus in their respective attack stat;
	 * melee weapons do not.
	 */
	public String getAttackStyle()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return "melee";
		}
		Item[] items = equipment.getItems();
		if (items.length <= SLOT_WEAPON)
		{
			return "melee";
		}
		Item weapon = items[SLOT_WEAPON];
		if (weapon == null || weapon.getId() == -1)
		{
			return "melee";
		}
		ItemStats stats = itemManager.getItemStats(weapon.getId());
		if (stats == null || !stats.isEquipable())
		{
			return "melee";
		}
		ItemEquipmentStats eq = stats.getEquipment();
		if (eq == null)
		{
			return "melee";
		}
		if (eq.getAmagic() > 0)
		{
			return "magic";
		}
		if (eq.getArange() > 0)
		{
			return "ranged";
		}
		return "melee";
	}

	/**
	 * Returns "magic", "ranged", or "melee" based on the weapon equipped by another player,
	 * read from their PlayerComposition. Used to infer the opponent's attack style.
	 */
	public String getAttackStyleForPlayer(Player player)
	{
		if (player == null || player.getPlayerComposition() == null)
		{
			return "melee";
		}
		int weaponId = player.getPlayerComposition().getEquipmentId(KitType.WEAPON);
		if (weaponId == -1)
		{
			return "melee";
		}
		ItemStats stats = itemManager.getItemStats(weaponId);
		if (stats == null || !stats.isEquipable())
		{
			return "melee";
		}
		ItemEquipmentStats eq = stats.getEquipment();
		if (eq == null)
		{
			return "melee";
		}
		if (eq.getAmagic() > 0)
		{
			return "magic";
		}
		if (eq.getArange() > 0)
		{
			return "ranged";
		}
		return "melee";
	}

	// Equipment-bearing KitTypes â€” excludes cosmetic slots (HAIR, JAW, ARMS) that carry
	// kit variation IDs rather than item IDs and would produce bogus ItemStats lookups.
	private static final KitType[] OPPONENT_EQUIPMENT_SLOTS = {
		KitType.HEAD, KitType.CAPE, KitType.AMULET, KitType.WEAPON,
		KitType.TORSO, KitType.SHIELD, KitType.LEGS, KitType.HANDS, KitType.BOOTS,
	};

	/**
	 * Returns the offensive gear bonuses for another player, read from their PlayerComposition.
	 * Covers HEAD/CAPE/AMULET/WEAPON/TORSO/SHIELD/LEGS/HANDS/BOOTS; excludes ring and ammo
	 * (not accessible via PlayerComposition). Attack bonuses are zeroed â€” only str/rstr/mdmg
	 * are needed for opponent kill-chance estimation.
	 */
	public GearBonuses getBonusesForPlayer(Player player)
	{
		if (player == null || player.getPlayerComposition() == null)
		{
			return zero();
		}

		int sStr = 0, sRstr = 0;
		float sMdmg = 0f;

		for (KitType kitType : OPPONENT_EQUIPMENT_SLOTS)
		{
			int itemId = player.getPlayerComposition().getEquipmentId(kitType);
			if (itemId <= 0)
			{
				continue;
			}
			ItemStats stats = itemManager.getItemStats(itemId);
			if (stats == null || !stats.isEquipable())
			{
				continue;
			}
			ItemEquipmentStats eq = stats.getEquipment();
			if (eq == null)
			{
				continue;
			}
			sStr  += eq.getStr();
			sRstr += eq.getRstr();
			sMdmg += eq.getMdmg();
		}

		return new GearBonuses(0, 0, 0, 0, 0, sStr, sRstr, sMdmg);
	}

	private static GearBonuses zero()
	{
		return new GearBonuses(0, 0, 0, 0, 0, 0, 0, 0f);
	}
}

package com.aipvpcoach;

import lombok.Value;
import java.util.LinkedHashMap;
import java.util.Map;

@Value
public class GearBonuses
{
	int attackStab;
	int attackSlash;
	int attackCrush;
	int attackMagic;
	int attackRanged;
	int strengthMelee;
	int strengthRanged;
	float strengthMagic;

	/**
	 * Computes per-style effectiveness as a percentage of the optimal bonuses.
	 * Returns 100% when the optimal bonus is 0 (can't do better than 0).
	 * Clamped to 0â€“100%.
	 */
	public Map<String, Integer> effectiveness(GearBonuses optimal)
	{
		Map<String, Integer> result = new LinkedHashMap<>();
		result.put("stab", pct(attackStab, optimal.attackStab));
		result.put("slash", pct(attackSlash, optimal.attackSlash));
		result.put("crush", pct(attackCrush, optimal.attackCrush));
		result.put("magic", pct(attackMagic, optimal.attackMagic));
		result.put("ranged", pct(attackRanged, optimal.attackRanged));
		result.put("str", pct(strengthMelee, optimal.strengthMelee));
		result.put("rstr", pct(strengthRanged, optimal.strengthRanged));
		result.put("mdmg", pctFloat(strengthMagic, optimal.strengthMagic));
		return result;
	}

	private static int pct(int current, int optimal)
	{
		if (optimal <= 0)
		{
			return 100;
		}
		int pct = (int) Math.round(100.0 * current / optimal);
		return Math.max(0, Math.min(100, pct));
	}

	private static int pctFloat(float current, float optimal)
	{
		if (optimal <= 0f)
		{
			return 100;
		}
		int pct = Math.round(100f * current / optimal);
		return Math.max(0, Math.min(100, pct));
	}
}

package com.aipvpcoach;

import java.util.HashMap;
import java.util.Map;

/**
 * Maps weapon item IDs to their primary melee sub-style ("stab", "slash", or "crush").
 * When the weapon is not in the map, falls back to the highest attack bonus in the
 * provided GearBonuses (offensive use). Returns null when both lookups fail (defensive use).
 */
public final class MeleeWeaponStyle
{
	// Common PvP melee weapons. Item IDs should be verified against the OSRS wiki.
	private static final Map<Integer, String> WEAPON_STYLES = new HashMap<>();

	static
	{
		// Slash
		WEAPON_STYLES.put(4151,  "slash"); // Abyssal whip
		WEAPON_STYLES.put(12006, "slash"); // Abyssal tentacle
		WEAPON_STYLES.put(4587,  "slash"); // Dragon scimitar
		WEAPON_STYLES.put(11802, "slash"); // Saradomin sword
		WEAPON_STYLES.put(25731, "slash"); // Blade of saeldor
		WEAPON_STYLES.put(25730, "slash"); // Blade of saeldor (c)
		WEAPON_STYLES.put(22325, "slash"); // Scythe of vitur
		WEAPON_STYLES.put(22486, "slash"); // Scythe of vitur (uncharged)
		WEAPON_STYLES.put(1305,  "slash"); // Dragon longsword
		WEAPON_STYLES.put(11806, "slash"); // Saradomin godsword
		WEAPON_STYLES.put(11808, "slash"); // Zamorak godsword
		WEAPON_STYLES.put(11810, "slash"); // Armadyl godsword
		WEAPON_STYLES.put(11804, "slash"); // Bandos godsword

		// Stab
		WEAPON_STYLES.put(22324, "stab");  // Ghrazi rapier
		WEAPON_STYLES.put(1215,  "stab");  // Dragon dagger
		WEAPON_STYLES.put(5698,  "stab");  // Dragon dagger (p+)
		WEAPON_STYLES.put(5700,  "stab");  // Dragon dagger (p++)
		WEAPON_STYLES.put(13265, "stab");  // Abyssal dagger
		WEAPON_STYLES.put(13271, "stab");  // Abyssal dagger (p+)
		WEAPON_STYLES.put(13273, "stab");  // Abyssal dagger (p++)
		WEAPON_STYLES.put(54489, "stab");  // Voidwaker
		WEAPON_STYLES.put(26219, "stab");  // Osmumten's fang
		WEAPON_STYLES.put(26215, "stab");  // Osmumten's fang (or)
		WEAPON_STYLES.put(11889, "stab");  // Zamorakian spear
		WEAPON_STYLES.put(26374, "stab");  // Zamorakian hasta

		// Crush
		WEAPON_STYLES.put(4153,  "crush"); // Granite maul
		WEAPON_STYLES.put(24225, "crush"); // Granite maul (or)
		WEAPON_STYLES.put(13576, "crush"); // Dragon warhammer
		WEAPON_STYLES.put(13263, "crush"); // Abyssal bludgeon
		WEAPON_STYLES.put(21003, "crush"); // Elder maul
		WEAPON_STYLES.put(24420, "crush"); // Inquisitor's mace
		WEAPON_STYLES.put(22542, "crush"); // Viggora's chainmace
		WEAPON_STYLES.put(27687, "crush"); // Ursine chainmace
	}

	private MeleeWeaponStyle() {}

	/**
	 * Resolves the melee sub-style for a weapon.
	 *
	 * For offensive use (player's own attack), pass the player's current GearBonuses as the
	 * fallback: when the weapon is not mapped, the sub-style with the highest attack bonus is used.
	 *
	 * For defensive use (opponent's weapon), pass null for gearBonuses: when the weapon is
	 * not mapped, null is returned so the caller can apply its own fallback (e.g. average
	 * of all three melee defense values).
	 *
	 * @param weaponId     item ID of the weapon, or -1 / 0 if unknown
	 * @param gearBonuses  offensive gear bonuses for fallback, or null to skip fallback
	 * @return "stab", "slash", "crush", or null if unresolvable
	 */
	public static String resolve(int weaponId, GearBonuses gearBonuses)
	{
		String mapped = WEAPON_STYLES.get(weaponId);
		if (mapped != null)
		{
			return mapped;
		}
		if (gearBonuses == null)
		{
			return null;
		}
		int stab  = gearBonuses.getAttackStab();
		int slash = gearBonuses.getAttackSlash();
		int crush = gearBonuses.getAttackCrush();
		if (stab >= slash && stab >= crush) return "stab";
		if (slash >= crush)                 return "slash";
		return "crush";
	}
}

package com.aipvpcoach;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

/**
 * Calculates the optimal {@link StatBoosts} a player could achieve based on
 * the potions currently in their inventory.
 *
 * The optimal is the ceiling â€” base level + best available pot boost â€” regardless
 * of whether the pot has actually been sipped. This lets us detect cases where a
 * player had a pot available but never used it (or partially decayed off it).
 *
 * Add new potions here as they are confirmed in-game.
 */
public final class PotionBoosts
{
	private PotionBoosts() {}

	/**
	 * Scans the inventory and returns the optimal stat levels for each tracked
	 * combat skill. If no relevant potion is found for a stat, optimal = base level
	 * (effectiveness will show 100% throughout unless the player brews down).
	 */
	public static StatBoosts calcOptimal(ItemContainer inv, ItemManager itemManager, Client client)
	{
		int baseAttack   = client.getRealSkillLevel(Skill.ATTACK);
		int baseStrength = client.getRealSkillLevel(Skill.STRENGTH);
		int baseRanged   = client.getRealSkillLevel(Skill.RANGED);
		int baseMagic    = client.getRealSkillLevel(Skill.MAGIC);

		int bestAttack   = baseAttack;
		int bestStrength = baseStrength;
		int bestRanged   = baseRanged;
		int bestMagic    = baseMagic;

		if (inv == null)
		{
			return new StatBoosts(bestAttack, bestStrength, bestRanged, bestMagic);
		}

		for (Item item : inv.getItems())
		{
			if (item.getId() == -1)
			{
				continue;
			}

			String name = stripDose(
				itemManager.getItemComposition(item.getId()).getName().toLowerCase().trim());

			switch (name)
			{
				// ---- Melee: both attack and strength ----
				case "super combat potion":
					bestAttack   = Math.max(bestAttack,   baseAttack   + superBoost(baseAttack));
					bestStrength = Math.max(bestStrength, baseStrength + superBoost(baseStrength));
					break;
				case "combat potion":
					bestAttack   = Math.max(bestAttack,   baseAttack   + regularBoost(baseAttack));
					bestStrength = Math.max(bestStrength, baseStrength + regularBoost(baseStrength));
					break;

				// ---- Attack only ----
				case "super attack":
					bestAttack = Math.max(bestAttack, baseAttack + superBoost(baseAttack));
					break;
				case "attack potion":
					bestAttack = Math.max(bestAttack, baseAttack + regularBoost(baseAttack));
					break;

				// ---- Strength only ----
				case "super strength":
					bestStrength = Math.max(bestStrength, baseStrength + superBoost(baseStrength));
					break;
				case "strength potion":
					bestStrength = Math.max(bestStrength, baseStrength + regularBoost(baseStrength));
					break;

				// ---- Ranged ----
				case "ranging potion":
				case "divine ranging potion":
				case "bastion potion":
				case "divine bastion potion":
					bestRanged = Math.max(bestRanged, baseRanged + rangedBoost(baseRanged));
					break;

				// ---- Magic ----
				case "saturated heart":
					bestMagic = Math.max(bestMagic, baseMagic + saturatedHeartBoost(baseMagic));
					break;
				case "imbued heart":
					bestMagic = Math.max(bestMagic, baseMagic + imbuedHeartBoost(baseMagic));
					break;
				case "magic potion":
					bestMagic = Math.max(bestMagic, baseMagic + 4);
					break;
			}
		}

		return new StatBoosts(bestAttack, bestStrength, bestRanged, bestMagic);
	}

	// -------------------------------------------------------------------------
	// Boost formulas
	// -------------------------------------------------------------------------

	/** Super attack / super strength / super combat: floor(level * 0.15) + 5 */
	private static int superBoost(int level)
	{
		return (int) Math.floor(level * 0.15) + 5;
	}

	/** Regular attack / strength / combat potion: floor(level * 0.10) + 3 */
	private static int regularBoost(int level)
	{
		return (int) Math.floor(level * 0.10) + 3;
	}

	/** Ranging / divine ranging / bastion / divine bastion: floor(level * 0.10) + 4 */
	private static int rangedBoost(int level)
	{
		return (int) Math.floor(level * 0.10) + 4;
	}

	/** Saturated heart: floor(level * 0.10) + 4 */
	private static int saturatedHeartBoost(int level)
	{
		return (int) Math.floor(level * 0.10) + 4;
	}

	/** Imbued heart: floor(level * 0.10) + 1 */
	private static int imbuedHeartBoost(int level)
	{
		return (int) Math.floor(level * 0.10) + 1;
	}

	// -------------------------------------------------------------------------
	// Helpers
	// -------------------------------------------------------------------------

	/** Strips trailing dose indicator, e.g. "super combat potion(4)" â†’ "super combat potion". */
	static String stripDose(String name)
	{
		int paren = name.lastIndexOf('(');
		if (paren > 0)
		{
			return name.substring(0, paren).trim();
		}
		return name;
	}
}

package com.aipvpcoach;

import lombok.Value;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Snapshot of a player's boosted combat stat levels at a point in time.
 * Used both to record the optimal (inventory-calculated ceiling) at fight start
 * and the current levels at each attack attempt.
 */
@Value
public class StatBoosts
{
	int attack;
	int strength;
	int ranged;
	int magic;

	/**
	 * Returns the relevant stat effectiveness as a percentage of the optimal levels
	 * for the given attack style. Capped at 0% on the low end (brews can take stats
	 * below base but never below 1 in-game). Values above 100% are allowed â€” they
	 * mean the player is better potted than at fight start.
	 */
	public Map<String, Integer> effectiveness(StatBoosts optimal, String attackStyle)
	{
		Map<String, Integer> result = new LinkedHashMap<>();
		if (attackStyle == null)
		{
			return result;
		}
		switch (attackStyle)
		{
			case "melee":
				result.put("str", pct(strength, optimal.strength));
				result.put("att", pct(attack, optimal.attack));
				break;
			case "ranged":
				result.put("range", pct(ranged, optimal.ranged));
				break;
			case "magic":
				result.put("magic", pct(magic, optimal.magic));
				break;
		}
		return result;
	}

	private static int pct(int current, int optimal)
	{
		if (optimal <= 0)
		{
			return 100;
		}
		return Math.max(0, (int) Math.round(100.0 * current / optimal));
	}
}

